entries.rtl:
module encoder8to3(d, y, valid);
  input [7:0] d;
  output reg [2:0] y;
  output valid;
  assign valid = |d;
  always @(*) begin
    case (d)
      8'h01: y = 3'd0;
      8'h02: y = 3'd1;
      8'h04: y = 3'd2;
      8'h08: y = 3'd3;
      8'h10: y = 3'd4;
      8'h20: y = 3'd5;
      8'h40: y = 3'd6;
      8'h80: y = 3'd7;
      default: y = 3'd0;
    endcase
  end
endmodule

