    bins op_sub = {1};
    bins op_and = {2};
    bins op_or  = {3};
    bins op_xor = {4};
    bins op_not = {5};
    bins op_shl = {6};
    bins op_shr = {7};
  }
  a_cp : coverpoint a {
    bins zero = {0};
    bins mid  = {[1:254]};
    bins max  = {255};
  }
  result_cp : coverpoint result {
    bins zero = {0};
    bins mid  = {[1:254]};
    bins max  = {255};
  }
  zero_cp : coverpoint zero {
    bins nonzero = {0};
    bins is_zero = {1};
