entries.rtl:
module alu8(a, b, op, result, zero);
  input [7:0] a, b;
  input [2:0] op;
  output reg [7:0] result;
  output zero;
  assign zero = (result == 8'b0);
  always @(*) begin
    case (op)
      3'd0: result = a + b;
      3'd1: result = a - b;
      3'd2: result = a & b;
      3'd3: result = a | b;
      3'd4: result = a ^ b;
      3'd5: result = ~a;
      3'd6: result = a << 1;
      3'd7: result = a >> 1;
    endcase
  end
endmodule

