entries.rtl:
module bcd_adder(a, b, cin, sum, cout);
  input [3:0] a, b;
  input cin;
  output reg [3:0] sum;
  output reg cout;
  reg [4:0] tmp;
  always @(*) begin
    tmp = a + b + cin;
    if (tmp > 9) begin
      sum  = tmp - 10;
      cout = 1'b1;
    end else begin
      sum  = tmp[3:0];
      cout = 1'b0;
    end
  end
endmodule

