entries.coverage_model:
covergroup cg_dff (ref logic d, q, rst_n) @(posedge clk);
  d_cp : coverpoint d {
    bins low  = {0};
    bins high = {1};
  }
  q_cp : coverpoint q {
    bins low  = {0};
    bins high = {1};
  }
  rst_cp : coverpoint rst_n {
    bins in_reset  = {0};
    bins out_reset = {1};
  }
  q_trans_cp : coverpoint q {
    bins rise = (0 => 1);
    bins fall = (1 => 0);
    bins hold_low  = (0 => 0);
    bins hold_high = (1 => 1);
  }
  d_x_rst : cross d_cp, rst_cp;
