entries.rtl:
module dff(clk, rst_n, d, q);
  input clk, rst_n, d;
  output reg q;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) q <= 1'b0;
    else        q <= d;
  end
endmodule

entries.coverage_model:
