entries.rtl:
module dff_en(clk, rst_n, en, d, q);
  input clk, rst_n, en, d;
  output reg q;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n)   q <= 1'b0;
    else if (en)  q <= d;
  end
endmodule

entries.coverage_model:
