entries.rtl:
module gray_counter(clk, rst_n, en, gray);
  input clk, rst_n, en;
  output [3:0] gray;
  reg [3:0] bin;
  assign gray = bin ^ (bin >> 1);
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n)  bin <= 4'b0;
    else if (en) bin <= bin + 1'b1;
  end
