entries.coverage_model:
covergroup cg_edge (ref logic din, rise, fall) @(posedge clk);
  din_cp : coverpoint din {
    bins low  = {0};
    bins high = {1};
  }
  pulse_cp : coverpoint {rise, fall} {
    bins steady  = {2'b00};
    bins falling = {2'b01};
    bins rising  = {2'b10};
    illegal_bins both = {2'b11};
  }
  din_trans_cp : coverpoint din {
    bins rise_edge = (0 => 1);
    bins fall_edge = (1 => 0);
    bins hold_low  = (0 => 0);
    bins hold_high = (1 => 1);
  }
