entries.rtl:
module sync_2ff(clk, rst_n, async_in, sync_out);
  input clk, rst_n, async_in;
  output sync_out;
  reg s1, s2;
  assign sync_out = s2;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      s1 <= 1'b0;
      s2 <= 1'b0;
    end else begin
      s1 <= async_in;
      s2 <= s1;
    end
  end
endmodule

entries.coverage_model:
covergroup cg_fifo (ref logic [3:0] cnt, ref logic wr_en, rd_en, full, empty) @(posedge clk);
  cnt_cp : coverpoint cnt {
    bins empty_c   = {0};
    bins almost_e  = {1};
    bins mid       = {[2:6]};
    bins almost_f  = {7};
    bins full_c    = {8};
    illegal_bins overflow = {[9:15]};
  }
  wr_cp : coverpoint wr_en {
    bins idle  = {0};
    bins write = {1};
  }
  rd_cp : coverpoint rd_en {
    bins idle = {0};
    bins read = {1};
  }
  full_cp : coverpoint full {
    bins not_full = {0};
    bins is_full  = {1};
  }
  empty_cp : coverpoint empty {
    bins not_empty = {0};
    bins is_empty  = {1};
  }
  cnt_trans_cp : coverpoint cnt {
    bins fill_up   = (7 => 8);
    bins drain_out = (1 => 0);
  }
  wr_x_rd    : cross wr_cp, rd_cp;
  wr_x_full  : cross wr_cp, full_cp;
  rd_x_empty : cross rd_cp, empty_cp;
endgroup

entries.rtl:
module fifo_sync(clk, rst_n, wr_en, rd_en, din, dout, full, empty);
  input clk, rst_n, wr_en, rd_en;
  input [7:0] din;
  output reg [7:0] dout;
  output full, empty;
  reg [7:0] mem [0:7];
  reg [3:0] cnt;
  reg [2:0] wptr, rptr;
  assign full  = (cnt == 4'd8);
  assign empty = (cnt == 4'd0);
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      cnt <= 0; wptr <= 0; rptr <= 0;
    end else begin
      if (wr_en && !full)  begin mem[wptr] <= din; wptr <= wptr + 1'b1; end
      if (rd_en && !empty) begin dout <= mem[rptr]; rptr <= rptr + 1'b1; end
      case ({wr_en && !full, rd_en && !empty})
        2'b10: cnt <= cnt + 1'b1;
        2'b01: cnt <= cnt - 1'b1;
        default: cnt <= cnt;
      endcase
    end
  end
endmodule

