  integer i;
  assign rdata1 = regs[raddr1];
  assign rdata2 = regs[raddr2];
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) for (i = 0; i < 8; i = i + 1) regs[i] <= 8'b0;
