entries.rtl:
module mailbox(clk, rst_n, put, get, din, dout, occupied);
  input clk, rst_n, put, get;
  input [7:0] din;
  output reg [7:0] dout;
  output reg occupied;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      occupied <= 1'b0;
      dout     <= 8'b0;
    end else if (put && !occupied) begin
      dout     <= din;
      occupied <= 1'b1;
    end else if (get && occupied) begin
      occupied <= 1'b0;
    end
  end
endmodule

entries.coverage_model:
covergroup cg_traffic (ref logic [1:0] state, ref logic timer_done) @(posedge clk);
