  }
  timer_cp : coverpoint timer_done {
    bins waiting = {0};
    bins expired = {1};
  }
  state_trans_cp : coverpoint state {
    bins red_to_green    = (2'd0 => 2'd1);
    bins green_to_yellow = (2'd1 => 2'd2);
    bins yellow_to_red   = (2'd2 => 2'd0);
    bins hold_red        = (2'd0 => 2'd0);
    bins hold_green      = (2'd1 => 2'd1);
