    bins zero = {0};
    bins one  = {1};
  }
  detected_cp : coverpoint detected {
    bins no_match = {0};
    bins match    = {1};
  }
  state_trans_cp : coverpoint state {
    bins build1 = (2'd0 => 2'd1);
    bins build2 = (2'd1 => 2'd2);
    bins fire   = (2'd2 => 2'd0);
