entries.rtl:
module arbiter_fixed(clk, rst_n, req, grant);
  input clk, rst_n;
  input [3:0] req;
  output reg [3:0] grant;
  always @(*) begin
    casex (req)
      4'bxxx1: grant = 4'b0001;
      4'bxx10: grant = 4'b0010;
      4'bx100: grant = 4'b0100;
      4'b1000: grant = 4'b1000;
      default: grant = 4'b0000;
