  }
  data_cp : coverpoint data {
    bins all_zero = {8'h00};
    bins all_one  = {8'hFF};
    bins mid      = {[8'h01:8'hFE]};
  }
  busy_cp : coverpoint busy {
    bins idle_b = {0};
    bins busy_b = {1};
  }
