  output [15:0] sum;
  output cout;
  wire [8:0] lo, hi0, hi1, hi;
  assign lo  = a[7:0]  + b[7:0] + cin;
  assign hi0 = a[15:8] + b[15:8];
  assign hi1 = a[15:8] + b[15:8] + 1'b1;
  assign hi  = lo[8] ? hi1 : hi0;
  assign sum  = {hi[7:0], lo[7:0]};
  assign cout = hi[8];
endmodule

