entries.rtl:
module hamming_enc4(data, code);
  input [3:0] data;
  output [6:0] code;
  wire p1, p2, p3;
  assign p1 = data[0] ^ data[1] ^ data[3];
  assign p2 = data[0] ^ data[2] ^ data[3];
  assign p3 = data[1] ^ data[2] ^ data[3];
  assign code = {data[3], data[2], data[1], p3, data[0], p2, p1};
