    bins err_pos[]  = {[3'd1:3'd7]};
  }
  corrected_cp : coverpoint corrected {
    bins clean     = {0};
    bins had_error = {1};
  }
  data_cp : coverpoint data {
    bins zero  = {4'h0};
    bins ones  = {4'hF};
    bins other = default;
