entries.rtl:
module hamming_dec7(code, data, syndrome, corrected);
  input [6:0] code;
  output [3:0] data;
  output [2:0] syndrome;
  output corrected;
  wire [6:0] fixed;
  assign syndrome[0] = code[0] ^ code[2] ^ code[4] ^ code[6];
  assign syndrome[1] = code[1] ^ code[2] ^ code[5] ^ code[6];
  assign syndrome[2] = code[3] ^ code[4] ^ code[5] ^ code[6];
  assign corrected   = (syndrome != 3'd0);
  assign fixed       = corrected ? (code ^ (7'b1 << (syndrome - 3'd1))) : code;
  assign data        = {fixed[6], fixed[5], fixed[4], fixed[2]};
endmodule

