entries.rtl:
module clamp8(din, lo, hi, dout, clamped_lo, clamped_hi);
  input [7:0] din, lo, hi;
  output reg [7:0] dout;
  output clamped_lo, clamped_hi;
  assign clamped_lo = (din < lo);
  assign clamped_hi = (din > hi);
  always @(*) begin
    if (din < lo)      dout = lo;
    else if (din > hi) dout = hi;
    else               dout = din;
  end
endmodule

