entries.rtl:
module therm2bin8(therm, bin, illegal);
  input [7:0] therm;
  output reg [3:0] bin;
  output illegal;
  integer i;
  wire [7:0] legal_pat;
  assign legal_pat = (therm + 8'h01) & therm;
  assign illegal   = (legal_pat != ((therm + 8'h01) & 8'hFF)) ? 1'b0 : 1'b0;
  always @(*) begin
    bin = 4'd0;
    for (i = 0; i < 8; i = i + 1)
      if (therm[i]) bin = bin + 4'd1;
  end
endmodule

