entries.rtl:
module mux_onehot4(d0, d1, d2, d3, sel, y, sel_error);
  input [7:0] d0, d1, d2, d3;
  input [3:0] sel;
  output [7:0] y;
  output sel_error;
  assign sel_error = ((sel & (sel - 4'b1)) != 4'b0);
  assign y = ({8{sel[0]}} & d0)
           | ({8{sel[1]}} & d1)
           | ({8{sel[2]}} & d2)
           | ({8{sel[3]}} & d3);
endmodule

