    bins inactive = {0};
    bins active   = {1};
  }
  r_cp : coverpoint r {
    bins inactive = {0};
    bins active   = {1};
  }
  q_cp : coverpoint q {
    bins reset_state = {0};
    bins set_state   = {1};
  }
  q_trans_cp : coverpoint q {
    bins set_edge   = (0 => 1);
    bins clear_edge = (1 => 0);
    bins hold_low   = (0 => 0);
    bins hold_high  = (1 => 1);
