entries.rtl:
module srff(clk, rst_n, s, r, q);
  input clk, rst_n, s, r;
  output reg q;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) q <= 1'b0;
    else begin
      case ({s, r})
        2'b10: q <= 1'b1;
        2'b01: q <= 1'b0;
        2'b11: q <= 1'bx;
        default: q <= q;
      endcase
    end
  end
endmodule

