entries.rtl:
module lfsr16(clk, rst_n, load, seed, lfsr, lockup);
  input clk, rst_n, load;
  input [15:0] seed;
  output reg [15:0] lfsr;
  output lockup;
  wire fb;
  assign fb     = lfsr[15] ^ lfsr[13] ^ lfsr[12] ^ lfsr[10];
  assign lockup = (lfsr == 16'h0000);
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n)     lfsr <= 16'hACE1;
    else if (load)  lfsr <= seed;
    else            lfsr <= {lfsr[14:0], fb};
  end
endmodule

