module counter_load8(clk, rst_n, load, en, din, count, tc);
  input clk, rst_n, load, en;
  input [7:0] din;
  output reg [7:0] count;
  output tc;
  assign tc = (count == 8'hFF);
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n)     count <= 8'h00;
    else if (load)  count <= din;
    else if (en)    count <= count + 8'd1;
  end
