    illegal_bins bad = {[10:15]};
  }
  ones_trans_cp : coverpoint ones {
    bins ones_roll = (4'd9 => 4'd0);
    bins ones_inc  = (4'd0 => 4'd1);
  }
  tens_trans_cp : coverpoint tens {
    bins tens_carry = (4'd0 => 4'd1);
    bins tens_roll  = (4'd9 => 4'd0);
  }
