entries.rtl:
module counter_bcd2(clk, rst_n, en, ones, tens, rollover);
  input clk, rst_n, en;
  output reg [3:0] ones, tens;
  output rollover;
  assign rollover = en && (ones == 4'd9) && (tens == 4'd9);
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      ones <= 4'd0; tens <= 4'd0;
    end else if (en) begin
      if (ones == 4'd9) begin
        ones <= 4'd0;
        tens <= (tens == 4'd9) ? 4'd0 : (tens + 4'd1);
      end else begin
        ones <= ones + 4'd1;
      end
    end
  end
endmodule

