entries.rtl:
module prescaler(clk, rst_n, ratio, tick, cnt);
  input clk, rst_n;
  input [7:0] ratio;
  output tick;
  output reg [7:0] cnt;
  assign tick = (cnt == 8'd0);
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n)          cnt <= ratio;
    else if (cnt == 8'd0) cnt <= ratio;
    else                  cnt <= cnt - 8'd1;
  end
endmodule

entries.coverage_model:
covergroup cg_pipe3 (ref logic [2:0] valid_pipe, ref logic stall, vin, vout) @(posedge clk);
