entries.rtl:
module pipeline_reg3(clk, rst_n, stall, din, vin, dout, vout, valid_pipe);
  input clk, rst_n, stall, vin;
  input [7:0] din;
  output [7:0] dout;
  output vout;
  output reg [2:0] valid_pipe;
  reg [7:0] s0, s1, s2;
  assign dout = s2;
  assign vout = valid_pipe[2];
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      valid_pipe <= 3'b000;
    end else if (!stall) begin
      s0 <= din; s1 <= s0; s2 <= s1;
      valid_pipe <= {valid_pipe[1:0], vin};
    end
  end
endmodule

entries.coverage_model:
