entries.coverage_model:
covergroup cg_dual_edge (ref logic din, din_q, rise, fall, any_edge) @(posedge clk);
  din_cp : coverpoint din {
    bins low  = {0};
    bins high = {1};
  }
  din_trans_cp : coverpoint din {
    bins rising    = (0 => 1);
    bins falling   = (1 => 0);
    bins hold_low  = (0 => 0);
    bins hold_high = (1 => 1);
  }
  rise_cp : coverpoint rise { bins idle = {0}; bins detected = {1}; }
  fall_cp : coverpoint fall { bins idle = {0}; bins detected = {1}; }
  any_cp  : coverpoint any_edge { bins idle = {0}; bins detected = {1}; }
  edge_cross : cross rise_cp, fall_cp {
    illegal_bins both = binsof(rise_cp.detected) && binsof(fall_cp.detected);
  }
  din_x_any : cross din_cp, any_cp;
endgroup

entries.rtl:
module dual_edge_detect(clk, rst_n, din, rise, fall, any_edge);
  input clk, rst_n, din;
  output rise, fall, any_edge;
  reg din_q;
  assign rise     = din & ~din_q;
  assign fall     = ~din & din_q;
  assign any_edge = rise | fall;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) din_q <= 1'b0;
    else        din_q <= din;
  end
endmodule

entries.coverage_model:
covergroup cg_glitch (ref logic din, dout, ref logic [2:0] stable_cnt) @(posedge clk);
  cnt_cp : coverpoint stable_cnt {
    bins settled  = {3'd0};
    bins counting = {[3'd1:3'd3]};
    bins threshold= {3'd4};
    illegal_bins over = {[3'd5:3'd7]};
  }
  din_cp  : coverpoint din  { bins low = {0}; bins high = {1}; }
  dout_cp : coverpoint dout { bins low = {0}; bins high = {1}; }
  dout_trans_cp : coverpoint dout {
    bins accept_rise = (0 => 1);
    bins accept_fall = (1 => 0);
  }
  cnt_trans_cp : coverpoint stable_cnt {
    bins glitch_reject = (3'd1 => 3'd0);
    bins full_window   = (3'd3 => 3'd4);
  }
  din_x_dout : cross din_cp, dout_cp;
endgroup

entries.rtl:
module glitch_filter(clk, rst_n, din, dout, stable_cnt);
  input clk, rst_n, din;
  output reg dout;
  output reg [2:0] stable_cnt;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      dout <= 1'b0; stable_cnt <= 3'd0;
    end else if (din == dout) begin
      stable_cnt <= 3'd0;
    end else if (stable_cnt == 3'd4) begin
      dout <= din; stable_cnt <= 3'd0;
    end else begin
      stable_cnt <= stable_cnt + 3'd1;
    end
  end
endmodule

entries.coverage_model:
covergroup cg_piso8 (ref logic [7:0] din, shifter, ref logic [3:0] bitcnt, ref logic load, sout, busy) @(posedge clk);
  bitcnt_cp : coverpoint bitcnt {
