  din_x_sout  : cross din_cp, sout_cp;
endgroup

entries.rtl:
module piso8(clk, rst_n, load, din, sout, busy, bitcnt);
  input clk, rst_n, load;
  input [7:0] din;
  output sout;
  output busy;
  output reg [3:0] bitcnt;
  reg [7:0] shifter;
  assign sout = shifter[7];
  assign busy = (bitcnt != 4'd0);
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      shifter <= 8'h00; bitcnt <= 4'd0;
    end else if (load) begin
      shifter <= din; bitcnt <= 4'd8;
    end else if (bitcnt != 4'd0) begin
      shifter <= {shifter[6:0], 1'b0};
      bitcnt  <= bitcnt - 4'd1;
    end
  end
endmodule

entries.coverage_model:
covergroup cg_sipo8 (ref logic [7:0] dout, ref logic [2:0] bitcnt, ref logic sin, en, done) @(posedge clk);
