  sin_cp : coverpoint sin { bins zero_bit = {0}; bins one_bit = {1}; }
  en_cp  : coverpoint en  { bins idle = {0}; bins shifting = {1}; }
  done_cp: coverpoint done{ bins partial = {0}; bins word_ready = {1}; }
  bitcnt_trans_cp : coverpoint bitcnt {
    bins wrap = (3'd7 => 3'd0);
  }
  bitcnt_x_sin : cross bitcnt_cp, sin_cp;
  en_x_done    : cross en_cp, done_cp;
endgroup

entries.rtl:
module sipo8(clk, rst_n, sin, en, dout, done, bitcnt);
  input clk, rst_n, sin, en;
  output reg [7:0] dout;
  output done;
  output reg [2:0] bitcnt;
  assign done = en && (bitcnt == 3'd7);
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      dout <= 8'h00; bitcnt <= 3'd0;
    end else if (en) begin
      dout   <= {dout[6:0], sin};
      bitcnt <= bitcnt + 3'd1;
    end
  end
endmodule

entries.coverage_model:
covergroup cg_univ_shift4 (ref logic [3:0] q, din, ref logic [1:0] mode, ref logic sin_l, sin_r) @(posedge clk);
