entries.rtl:
module univ_shift4(clk, rst_n, mode, sin_l, sin_r, din, q);
  input clk, rst_n, sin_l, sin_r;
  input [1:0] mode;
  input [3:0] din;
  output reg [3:0] q;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) q <= 4'b0000;
    else begin
      case (mode)
        2'd0: q <= q;
        2'd1: q <= {sin_r, q[3:1]};
        2'd2: q <= {q[2:0], sin_l};
        2'd3: q <= din;
      endcase
    end
  end
endmodule

