entries.rtl:
module pulse_sync(sclk, dclk, rst_n, src_pulse, toggle, sync_q, dst_pulse);
  input sclk, dclk, rst_n, src_pulse;
  output reg toggle;
  output reg [2:0] sync_q;
  output dst_pulse;
  assign dst_pulse = sync_q[2] ^ sync_q[1];
  always @(posedge sclk or negedge rst_n) begin
    if (!rst_n)         toggle <= 1'b0;
    else if (src_pulse) toggle <= ~toggle;
  end
  always @(posedge dclk or negedge rst_n) begin
    if (!rst_n) sync_q <= 3'b000;
    else        sync_q <= {sync_q[1:0], toggle};
  end
endmodule

entries.coverage_model:
covergroup cg_gray_sync4 (ref logic [3:0] gray_out, sync1, sync2) @(posedge dclk);
