    if (!rst_n) gray_out <= 4'b0000;
    else        gray_out <= bin_in ^ (bin_in >> 1);
  end
  always @(posedge dclk or negedge rst_n) begin
    if (!rst_n) begin
      sync1 <= 4'b0000; sync2 <= 4'b0000;
