    bins granted = {1};
  }
  tokens_trans_cp : coverpoint tokens {
    bins hit_empty = (4'd1 => 4'd0);
    bins hit_full  = (4'd14 => 4'd15);
  }
  refill_x_grant : cross refill_cp, grant_cp;
  tokens_x_req   : cross tokens_cp, req_cp;
