entries.rtl:
module token_bucket(clk, rst_n, refill, req, grant, tokens);
  input clk, rst_n, refill, req;
  output grant;
  output reg [3:0] tokens;
  assign grant = req && (tokens != 4'd0);
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) tokens <= 4'd0;
    else begin
      case ({refill && (tokens != 4'd15), grant})
        2'b10: tokens <= tokens + 4'd1;
        2'b01: tokens <= tokens - 4'd1;
        default: tokens <= tokens;
      endcase
    end
