endmodule

entries.coverage_model:
covergroup cg_stopwatch (ref logic [5:0] secs, mins, ref logic run, clr) @(posedge clk);
  secs_cp : coverpoint secs {
    bins zero = {6'd0};
    bins mid  = {[6'd1:6'd58]};
    bins max  = {6'd59};
    illegal_bins bad = {[6'd60:6'd63]};
  }
  mins_cp : coverpoint mins {
    bins zero = {6'd0};
    bins mid  = {[6'd1:6'd58]};
    bins max  = {6'd59};
    illegal_bins bad = {[6'd60:6'd63]};
  }
  run_cp : coverpoint run {
