endgroup

entries.rtl:
module stopwatch(clk, rst_n, run, clr, secs, mins);
  input clk, rst_n, run, clr;
  output reg [5:0] secs;
  output reg [5:0] mins;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n || clr) begin
      secs <= 6'd0; mins <= 6'd0;
    end else if (run) begin
      if (secs == 6'd59) begin
        secs <= 6'd0;
        mins <= (mins == 6'd59) ? 6'd0 : (mins + 6'd1);
      end else begin
        secs <= secs + 6'd1;
      end
    end
  end
endmodule

entries.coverage_model:
covergroup cg_freq_cnt (ref logic [7:0] count, result, ref logic gate, sig, sat) @(posedge clk);
  count_cp : coverpoint count {
    bins zero = {8'h00};
    bins low  = {[8'h01:8'h7F]};
    bins high = {[8'h80:8'hFE]};
    bins full = {8'hFF};
  }
  result_cp : coverpoint result {
    bins zero = {8'h00};
    bins mid  = {[8'h01:8'hFE]};
    bins full = {8'hFF};
  }
  gate_cp : coverpoint gate {
    bins closed = {0};
    bins open   = {1};
  }
  gate_trans_cp : coverpoint gate {
    bins window_open  = (0 => 1);
    bins window_close = (1 => 0);
  }
  sat_cp : coverpoint sat {
    bins in_range   = {0};
    bins saturated  = {1};
  }
