entries.rtl:
module freq_counter(clk, rst_n, sig, gate, count, result, sat);
  input clk, rst_n, sig, gate;
  output reg [7:0] count;
  output reg [7:0] result;
  output sat;
  reg sig_q, gate_q;
  wire sig_edge;
  assign sig_edge = sig & ~sig_q;
  assign sat      = (count == 8'hFF);
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      count <= 8'h00; result <= 8'h00; sig_q <= 1'b0; gate_q <= 1'b0;
    end else begin
      sig_q  <= sig;
      gate_q <= gate;
      if (gate_q && !gate) begin
        result <= count;
        count  <= 8'h00;
      end else if (gate && sig_edge && !sat) begin
        count <= count + 8'd1;
      end
    end
  end
endmodule

entries.coverage_model:
