    bins low_duty   = {[8'h01:8'h3F]};
    bins mid_duty   = {[8'h40:8'hBF]};
    bins high_duty  = {[8'hC0:8'hFF]};
  }
  period_cp : coverpoint period_lat {
    bins short_period = {[8'h01:8'h1F]};
    bins mid_period   = {[8'h20:8'h7F]};
    bins long_period  = {[8'h80:8'hFF]};
    bins no_period    = {8'h00};
  }
  sig_cp : coverpoint sig {
    bins low  = {0};
    bins high = {1};
  }
  sig_trans_cp : coverpoint sig {
    bins rising  = (0 => 1);
    bins falling = (1 => 0);
    bins stuck_high = (1 => 1 => 1);
    bins stuck_low  = (0 => 0 => 0);
