endgroup

entries.rtl:
module duty_meas(clk, rst_n, sig, high_cnt, period_cnt, high_lat, period_lat);
  input clk, rst_n, sig;
  output reg [7:0] high_cnt, period_cnt, high_lat, period_lat;
  reg sig_q;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      high_cnt <= 0; period_cnt <= 0; high_lat <= 0; period_lat <= 0; sig_q <= 0;
    end else begin
      sig_q <= sig;
      if (sig & ~sig_q) begin
        high_lat   <= high_cnt;
        period_lat <= period_cnt;
        high_cnt   <= 8'd0;
        period_cnt <= 8'd1;
      end else begin
        if (sig) high_cnt <= high_cnt + 8'd1;
        period_cnt <= period_cnt + 8'd1;
      end
    end
  end
endmodule

entries.coverage_model:
