module sat_counter8(clk, rst_n, inc, dec, count, at_max, at_min);
  input clk, rst_n, inc, dec;
  output reg [7:0] count;
  output at_max, at_min;
  assign at_max = (count == 8'hFF);
  assign at_min = (count == 8'h00);
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) count <= 8'h00;
    else begin
      case ({inc, dec})
        2'b10: if (!at_max) count <= count + 8'd1;
        2'b01: if (!at_min) count <= count - 8'd1;
        default: count <= count;
      endcase
    end
  end
endmodule

