module checksum_accum8(clk, rst_n, en, clr, din, sum, carry);
  input clk, rst_n, en, clr;
  input [7:0] din;
  output reg [7:0] sum;
  output reg carry;
  wire [8:0] raw;
  assign raw = {1'b0, sum} + {1'b0, din};
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n || clr) begin
      sum <= 8'h00; carry <= 1'b0;
    end else if (en) begin
      sum   <= raw[7:0] + {7'b0, raw[8]};
      carry <= raw[8];
