entries.rtl:
module fifo_async(wclk, rclk, rst_n, wr_en, rd_en, din, dout, full, empty);
  input wclk, rclk, rst_n, wr_en, rd_en;
  input [7:0] din;
  output reg [7:0] dout;
  output full, empty;
  reg [7:0] mem [0:7];
  reg [3:0] wbin, rbin, wgray, rgray, wq1, wq2, rq1, rq2;
  wire [3:0] wbin_nxt, rbin_nxt;
  assign wbin_nxt = wbin + (wr_en && !full);
  assign rbin_nxt = rbin + (rd_en && !empty);
  assign full  = (wgray == {~rq2[3:2], rq2[1:0]});
  assign empty = (rgray == wq2);
  always @(posedge wclk or negedge rst_n) begin
    if (!rst_n) begin
      wbin <= 0; wgray <= 0; rq1 <= 0; rq2 <= 0;
    end else begin
      if (wr_en && !full) mem[wbin[2:0]] <= din;
      wbin  <= wbin_nxt;
      wgray <= wbin_nxt ^ (wbin_nxt >> 1);
      rq1   <= rgray; rq2 <= rq1;
    end
  end
  always @(posedge rclk or negedge rst_n) begin
    if (!rst_n) begin
      rbin <= 0; rgray <= 0; wq1 <= 0; wq2 <= 0;
    end else begin
      if (rd_en && !empty) dout <= mem[rbin[2:0]];
      rbin  <= rbin_nxt;
      rgray <= rbin_nxt ^ (rbin_nxt >> 1);
      wq1   <= wgray; wq2 <= wq1;
    end
  end
endmodule

