  in_ready_cp  : coverpoint in_ready  { bins stalled = {0}; bins ready = {1}; }
  out_valid_cp : coverpoint out_valid { bins idle = {0}; bins valid = {1}; }
  out_ready_cp : coverpoint out_ready { bins backpressure = {0}; bins ready = {1}; }
  skid_cp : coverpoint skid_full {
    bins empty    = {0};
    bins occupied = {1};
  }
  skid_trans_cp : coverpoint skid_full {
    bins capture = (0 => 1);
    bins drain   = (1 => 0);
    bins held    = (1 => 1);
  }
  handshake_in  : cross in_valid_cp, in_ready_cp;
