entries.rtl:
module skid_buffer(clk, rst_n, in_valid, in_data, in_ready, out_valid, out_data, out_ready, skid_full);
  input clk, rst_n, in_valid, out_ready;
  input [7:0] in_data;
  output in_ready, out_valid;
  output reg [7:0] out_data;
  output reg skid_full;
  reg [7:0] skid_data;
  assign in_ready  = !skid_full;
  assign out_valid = skid_full || in_valid;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      skid_full <= 1'b0;
    end else begin
      if (!out_ready && in_valid && !skid_full) begin
        skid_data <= in_data;
        skid_full <= 1'b1;
      end else if (out_ready && skid_full) begin
        skid_full <= 1'b0;
      end
    end
    out_data <= skid_full ? skid_data : in_data;
  end
endmodule

