  output reg [15:0] dout_a, dout_b;
  output collision;
  reg [15:0] mem [0:15];
  assign collision = we_a && we_b && (addr_a == addr_b);
  always @(posedge clk) begin
    if (we_a) mem[addr_a] <= din_a;
    dout_a <= mem[addr_a];
