    bins mid  = {[4'h1:4'hE]};
    bins max  = {4'hF};
  }
  valid_cp : coverpoint valid_arr {
    bins all_invalid = {4'b0000};
    bins all_valid   = {4'b1111};
    bins partial     = default;
  }
  hit_cp  : coverpoint hit  { bins no_hit = {0}; bins cache_hit = {1}; }
  miss_cp : coverpoint miss { bins no_miss = {0}; bins cache_miss = {1}; }
  fill_cp : coverpoint fill { bins idle = {0}; bins filling = {1}; }
  valid_trans_cp : coverpoint valid_arr {
    bins first_fill = (4'b0000 => 4'b0001);
  }
  index_x_hit  : cross index_cp, hit_cp;
  index_x_miss : cross index_cp, miss_cp;
