entries.rtl:
module cache_dm(clk, rst_n, req, addr, hit, miss, fill);
  input clk, rst_n, req, fill;
  input [7:0] addr;
  output hit, miss;
  reg [3:0] tag_arr [0:3];
  reg [3:0] valid_arr;
  wire [1:0] index;
  wire [3:0] tag;
  assign index = addr[3:2];
  assign tag   = addr[7:4];
  assign hit   = req && valid_arr[index] && (tag_arr[index] == tag);
  assign miss  = req && !hit;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) valid_arr <= 4'b0000;
    else if (fill) begin
      tag_arr[index]   <= tag;
      valid_arr[index] <= 1'b1;
    end
  end
endmodule

entries.coverage_model:
covergroup cg_cache_state (ref logic [1:0] state, ref logic alloc, write, writeback, inval) @(posedge clk);
