    bins clean   = {2'd1};
    bins dirty   = {2'd2};
    illegal_bins unused = {2'd3};
  }
  state_trans_cp : coverpoint state {
    bins allocate      = (2'd0 => 2'd1);
    bins dirty_write   = (2'd1 => 2'd2);
    bins writeback     = (2'd2 => 2'd1);
    bins inval_clean   = (2'd1 => 2'd0);
    bins inval_dirty   = (2'd2 => 2'd0);
    bins stay_dirty    = (2'd2 => 2'd2);
  }
  alloc_cp : coverpoint alloc { bins idle = {0}; bins allocating = {1}; }
  write_cp : coverpoint write { bins idle = {0}; bins writing = {1}; }
  wb_cp    : coverpoint writeback { bins idle = {0}; bins evicting = {1}; }
  inval_cp : coverpoint inval { bins idle = {0}; bins invalidating = {1}; }
