entries.rtl:
module cache_line_state(clk, rst_n, alloc, write, writeback, inval, state);
  input clk, rst_n, alloc, write, writeback, inval;
  output reg [1:0] state;
  parameter INVALID = 2'd0, CLEAN = 2'd1, DIRTY = 2'd2;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) state <= INVALID;
    else if (inval) state <= INVALID;
    else begin
      case (state)
        INVALID: if (alloc)     state <= CLEAN;
        CLEAN:   if (write)     state <= DIRTY;
        DIRTY:   if (writeback) state <= CLEAN;
        default: state <= INVALID;
      endcase
    end
  end
endmodule

