entries.rtl:
module tag_array4(clk, rst_n, we, way, tag_in, tag_lookup, match, match_way);
  input clk, rst_n, we;
  input [1:0] way;
  input [3:0] tag_in, tag_lookup;
  output match;
  output reg [1:0] match_way;
  reg [3:0] tags [0:3];
  reg [3:0] valid;
  integer i;
  reg found;
  assign match = found;
  always @(*) begin
    found = 1'b0; match_way = 2'd0;
    for (i = 0; i < 4; i = i + 1)
      if (valid[i] && (tags[i] == tag_lookup)) begin
        found = 1'b1; match_way = i[1:0];
      end
  end
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) valid <= 4'b0000;
    else if (we) begin
      tags[way]  <= tag_in;
      valid[way] <= 1'b1;
    end
  end
endmodule

