  sp_cp : coverpoint sp {
    bins empty = {4'd0};
    bins mid   = {[4'd1:4'd7]};
    bins full  = {4'd8};
    illegal_bins bad = {[4'd9:4'd15]};
  }
  push_cp : coverpoint push { bins idle = {0}; bins pushing = {1}; }
  pop_cp  : coverpoint pop  { bins idle = {0}; bins popping = {1}; }
  ovf_cp  : coverpoint overflow  { bins ok = {0}; bins error = {1}; }
  udf_cp  : coverpoint underflow { bins ok = {0}; bins error = {1}; }
  sp_trans_cp : coverpoint sp {
    bins fill_last  = (4'd7 => 4'd8);
    bins drain_last = (4'd1 => 4'd0);
    bins hold_full  = (4'd8 => 4'd8);
    bins hold_empty = (4'd0 => 4'd0);
  }
  push_x_pop : cross push_cp, pop_cp;
  sp_x_push  : cross sp_cp, push_cp;
  sp_x_pop   : cross sp_cp, pop_cp;
