entries.rtl:
module stack_guard(clk, rst_n, push, pop, din, dout, sp, overflow, underflow);
  input clk, rst_n, push, pop;
  input [7:0] din;
  output reg [7:0] dout;
  output reg [3:0] sp;
  output overflow, underflow;
  reg [7:0] mem [0:7];
  assign overflow  = push && !pop && (sp == 4'd8);
  assign underflow = pop && !push && (sp == 4'd0);
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) sp <= 4'd0;
    else begin
      case ({push && !overflow, pop && !underflow})
        2'b10: begin mem[sp[2:0]] <= din; sp <= sp + 4'd1; end
        2'b01: begin dout <= mem[sp[2:0] - 3'd1]; sp <= sp - 4'd1; end
        default: sp <= sp;
      endcase
    end
  end
endmodule

