  prio_in_cp : coverpoint prio_in {
    bins level[] = {[0:3]};
  }
  prio_out_cp : coverpoint prio_out {
    bins level[] = {[0:3]};
  }
  count_cp : coverpoint count {
    bins empty = {3'd0};
    bins mid   = {[3'd1:3'd3]};
    bins full  = {3'd4};
    illegal_bins bad = {[3'd5:3'd7]};
  }
  push_cp : coverpoint push { bins idle = {0}; bins pushing = {1}; }
  pop_cp  : coverpoint pop  { bins idle = {0}; bins popping = {1}; }
  count_trans_cp : coverpoint count {
    bins fill_full  = (3'd3 => 3'd4);
    bins drain_last = (3'd1 => 3'd0);
  }
  push_x_full  : cross push_cp, full;
  pop_x_empty  : cross pop_cp, empty;
  in_x_out     : cross prio_in_cp, prio_out_cp;
