entries.rtl:
module prio_queue4(clk, rst_n, push, pop, prio_in, prio_out, count, full, empty);
  input clk, rst_n, push, pop;
  input [1:0] prio_in;
  output reg [1:0] prio_out;
  output reg [2:0] count;
  output full, empty;
  reg [1:0] q [0:3];
  integer i, best;
  assign full  = (count == 3'd4);
  assign empty = (count == 3'd0);
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) count <= 3'd0;
    else begin
      if (push && !full) begin
        q[count[1:0]] <= prio_in;
        count <= count + 3'd1;
      end else if (pop && !empty) begin
        best = 0;
        for (i = 1; i < 4; i = i + 1)
          if (i < count && q[i] > q[best]) best = i;
        prio_out <= q[best];
        q[best]  <= q[count - 3'd1];
        count    <= count - 3'd1;
      end
    end
  end
endmodule

