entries.rtl:
module ping_pong_buf(clk, rst_n, wr_en, rd_en, swap, din, dout, wbank, wcount);
  input clk, rst_n, wr_en, rd_en, swap;
  input [7:0] din;
  output reg [7:0] dout;
  output reg wbank;
  output reg [2:0] wcount;
  reg [7:0] bank0 [0:7];
  reg [7:0] bank1 [0:7];
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      wbank <= 1'b0; wcount <= 3'd0;
    end else begin
      if (wr_en) begin
        if (wbank) bank1[wcount] <= din;
        else       bank0[wcount] <= din;
        wcount <= wcount + 3'd1;
      end
      if (rd_en) dout <= wbank ? bank0[wcount] : bank1[wcount];
      if (swap && (wcount == 3'd7)) begin
        wbank  <= ~wbank;
        wcount <= 3'd0;
      end
    end
  end
endmodule

