module multibank_mem(clk, we, addr, din, dout, bank, offset);
  input clk, we;
  input [5:0] addr;
  input [7:0] din;
  output reg [7:0] dout;
  output [1:0] bank;
  output [3:0] offset;
  reg [7:0] mem0 [0:15];
  reg [7:0] mem1 [0:15];
  reg [7:0] mem2 [0:15];
  reg [7:0] mem3 [0:15];
  assign bank   = addr[5:4];
  assign offset = addr[3:0];
  always @(posedge clk) begin
    if (we) begin
      case (bank)
        2'd0: mem0[offset] <= din;
        2'd1: mem1[offset] <= din;
        2'd2: mem2[offset] <= din;
        2'd3: mem3[offset] <= din;
      endcase
    end else begin
      case (bank)
        2'd0: dout <= mem0[offset];
        2'd1: dout <= mem1[offset];
        2'd2: dout <= mem2[offset];
        2'd3: dout <= mem3[offset];
      endcase
    end
  end
endmodule

