module regbank_mm(clk, rst_n, sel, we, offset, wdata, rdata, err);
  input clk, rst_n, sel, we;
  input [2:0] offset;
  input [7:0] wdata;
  output reg [7:0] rdata;
  output err;
  reg [7:0] ctrl, cfg, scratch;
  wire [7:0] status;
  assign status = 8'hA5;
  assign err    = sel && (offset > 3'd3);
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      ctrl <= 8'h00; cfg <= 8'h00; scratch <= 8'h00;
    end else if (sel && we) begin
      case (offset)
        3'd0: ctrl    <= wdata;
        3'd1: cfg     <= wdata;
        3'd3: scratch <= wdata;
        default: ;
      endcase
    end
  end
  always @(*) begin
    case (offset)
      3'd0: rdata = ctrl;
      3'd1: rdata = cfg;
      3'd2: rdata = status;
      3'd3: rdata = scratch;
      default: rdata = 8'h00;
    endcase
  end
endmodule

