    bins partial = default;
  }
  insert_cp : coverpoint insert { bins idle = {0}; bins inserting = {1}; }
  lookup_cp : coverpoint lookup { bins idle = {0}; bins looking = {1}; }
  hit_cp    : coverpoint hit    { bins miss = {0}; bins found = {1}; }
  collision_cp : coverpoint collision {
