entries.rtl:
module hash_bucket(clk, rst_n, insert, lookup, key, hit, collision, occupied);
  input clk, rst_n, insert, lookup;
  input [7:0] key;
  output hit, collision;
  output reg [3:0] occupied;
  reg [7:0] slot [0:3];
  wire [1:0] idx;
  assign idx       = key[1:0] ^ key[3:2];
  assign hit       = lookup && occupied[idx] && (slot[idx] == key);
  assign collision = insert && occupied[idx] && (slot[idx] != key);
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) occupied <= 4'b0000;
    else if (insert && !collision) begin
      slot[idx]     <= key;
      occupied[idx] <= 1'b1;
    end
  end
endmodule

