entries.rtl:
module desc_ring(clk, rst_n, produce, consume, head, tail, full, empty, own);
  input clk, rst_n, produce, consume;
  output reg [2:0] head, tail;
  output full, empty;
  output reg [3:0] own;
  assign full  = ((head + 3'd1) == tail);
  assign empty = (head == tail);
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      head <= 3'd0; tail <= 3'd0; own <= 4'b0000;
    end else begin
      if (produce && !full) begin
        own[head[1:0]] <= 1'b1;
        head <= head + 3'd1;
      end
      if (consume && !empty) begin
        own[tail[1:0]] <= 1'b0;
        tail <= tail + 3'd1;
      end
    end
  end
endmodule

entries.coverage_model:
covergroup cg_seq1101 (ref logic [2:0] state, ref logic din, detect) @(posedge clk);
  state_cp : coverpoint state {
    bins s0    = {3'd0};
    bins s1    = {3'd1};
    bins s11   = {3'd2};
    bins s110  = {3'd3};
    bins s1101 = {3'd4};
    illegal_bins unused = {[3'd5:3'd7]};
