entries.rtl:
module seq_detect_1101(clk, rst_n, din, state, detect);
  input clk, rst_n, din;
  output reg [2:0] state;
  output detect;
  parameter S0=3'd0, S1=3'd1, S11=3'd2, S110=3'd3, S1101=3'd4;
  assign detect = (state == S1101);
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) state <= S0;
    else begin
      case (state)
        S0:    state <= din ? S1   : S0;
        S1:    state <= din ? S11  : S0;
        S11:   state <= din ? S11  : S110;
        S110:  state <= din ? S1101: S0;
        S1101: state <= din ? S11  : S110;
        default: state <= S0;
      endcase
    end
  end
endmodule

