entries.rtl:
module elevator_fsm(clk, rst_n, req_floor, req, at_floor, state, floor, door_open);
  input clk, rst_n, req, at_floor;
  input [1:0] req_floor;
  output reg [1:0] state, floor;
  output door_open;
  parameter IDLE=2'd0, UP=2'd1, DOWN=2'd2, DOOR=2'd3;
  assign door_open = (state == DOOR);
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state <= IDLE; floor <= 2'd0;
    end else begin
      case (state)
        IDLE: if (req) state <= (req_floor > floor) ? UP :
                                (req_floor < floor) ? DOWN : DOOR;
        UP:   if (at_floor) begin
                floor <= floor + 2'd1;
                if ((floor + 2'd1) == req_floor) state <= DOOR;
              end
        DOWN: if (at_floor) begin
                floor <= floor - 2'd1;
                if ((floor - 2'd1) == req_floor) state <= DOOR;
              end
        DOOR: state <= IDLE;
      endcase
    end
  end
endmodule

