entries.rtl:
module door_lock_fsm(clk, rst_n, digit_ok, digit_valid, reset_code, state, attempts, unlocked);
  input clk, rst_n, digit_ok, digit_valid, reset_code;
  output reg [1:0] state;
  output reg [1:0] attempts;
  output unlocked;
  parameter LOCKED=2'd0, ENTRY=2'd1, OPEN=2'd2, LOCKOUT=2'd3;
  reg [1:0] digits;
  assign unlocked = (state == OPEN);
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state <= LOCKED; attempts <= 2'd0; digits <= 2'd0;
    end else begin
      case (state)
        LOCKED: if (digit_valid) begin
                  state  <= digit_ok ? ENTRY : LOCKED;
                  digits <= 2'd1;
                end
        ENTRY:  if (digit_valid) begin
                  if (!digit_ok) begin
                    state    <= (attempts == 2'd2) ? LOCKOUT : LOCKED;
                    attempts <= attempts + 2'd1;
                  end else if (digits == 2'd3) begin
                    state <= OPEN; attempts <= 2'd0;
                  end else begin
                    digits <= digits + 2'd1;
                  end
                end
        OPEN:   if (reset_code) state <= LOCKED;
        LOCKOUT:if (reset_code) begin
                  state <= LOCKED; attempts <= 2'd0;
                end
      endcase
    end
  end
endmodule

