module atm_fsm(clk, rst_n, card_in, pin_ok, pin_bad, amount_ok, done, state, dispense);
  input clk, rst_n, card_in, pin_ok, pin_bad, amount_ok, done;
  output reg [2:0] state;
  output dispense;
  parameter IDLE=3'd0, CARD=3'd1, PIN=3'd2, SELECT=3'd3, DISPENSE=3'd4, EJECT=3'd5;
  assign dispense = (state == DISPENSE);
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) state <= IDLE;
    else begin
      case (state)
        IDLE:     if (card_in)   state <= CARD;
        CARD:     state <= PIN;
        PIN:      if (pin_ok)    state <= SELECT;
                  else if (pin_bad) state <= CARD;
        SELECT:   if (amount_ok) state <= DISPENSE;
                  else           state <= EJECT;
        DISPENSE: if (done)      state <= EJECT;
        EJECT:    state <= IDLE;
        default:  state <= IDLE;
      endcase
    end
  end
endmodule

