entries.rtl:
module washer_fsm(clk, rst_n, start, door_closed, timer_done, cancel, state, motor);
  input clk, rst_n, start, door_closed, timer_done, cancel;
  output reg [2:0] state;
  output motor;
  parameter IDLE=3'd0, FILL=3'd1, WASH=3'd2, RINSE=3'd3, SPIN=3'd4, DONE=3'd5, PAUSE=3'd6;
  assign motor = (state == WASH) || (state == RINSE) || (state == SPIN);
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) state <= IDLE;
    else if (cancel) state <= IDLE;
    else if (!door_closed && motor) state <= PAUSE;
    else begin
      case (state)
        IDLE:  if (start && door_closed) state <= FILL;
        FILL:  if (timer_done) state <= WASH;
        WASH:  if (timer_done) state <= RINSE;
        RINSE: if (timer_done) state <= SPIN;
        SPIN:  if (timer_done) state <= DONE;
        DONE:  state <= IDLE;
        PAUSE: if (door_closed) state <= WASH;
        default: state <= IDLE;
      endcase
    end
  end
endmodule

