entries.rtl:
module arbiter_weighted(clk, rst_n, req, grant, credit0, credit1);
  input clk, rst_n;
  input [1:0] req;
  output reg [1:0] grant;
  output reg [2:0] credit0, credit1;
  wire reload;
  assign reload = (credit0 == 3'd0) && (credit1 == 3'd0);
  always @(*) begin
    grant = 2'b00;
    if (req[0] && (credit0 != 3'd0))      grant = 2'b01;
    else if (req[1] && (credit1 != 3'd0)) grant = 2'b10;
    else if (req[0])                      grant = 2'b01;
    else if (req[1])                      grant = 2'b10;
  end
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      credit0 <= 3'd4; credit1 <= 3'd2;
    end else if (reload) begin
      credit0 <= 3'd4; credit1 <= 3'd2;
    end else begin
      if (grant[0] && (credit0 != 3'd0)) credit0 <= credit0 - 3'd1;
      if (grant[1] && (credit1 != 3'd0)) credit1 <= credit1 - 3'd1;
    end
  end
endmodule

