module req_ack_4phase(clk, rst_n, start, ack, req, phase);
  input clk, rst_n, start, ack;
  output reg req;
  output reg [1:0] phase;
  parameter IDLE=2'd0, ASSERT=2'd1, WAIT_ACK=2'd2, DEASSERT=2'd3;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      req <= 1'b0; phase <= IDLE;
    end else begin
      case (phase)
        IDLE:     if (start) begin req <= 1'b1; phase <= ASSERT; end
        ASSERT:   if (ack) phase <= WAIT_ACK;
        WAIT_ACK: begin req <= 1'b0; phase <= DEASSERT; end
        DEASSERT: if (!ack) phase <= IDLE;
      endcase
    end
  end
endmodule

