module axi_lite_write(clk, rst_n, awvalid, awready, wvalid, wready, bvalid, bready, bresp, state);
  input clk, rst_n, awvalid, wvalid, bready;
  output reg awready, wready, bvalid;
  output reg [1:0] bresp;
  output reg [1:0] state;
  parameter IDLE=2'd0, ADDR=2'd1, DATA=2'd2, RESP=2'd3;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state <= IDLE; awready <= 1'b0; wready <= 1'b0; bvalid <= 1'b0; bresp <= 2'b00;
    end else begin
      case (state)
        IDLE: begin
          awready <= 1'b1; wready <= 1'b1;
          if (awvalid && wvalid)      state <= RESP;
          else if (awvalid)           state <= DATA;
          else if (wvalid)            state <= ADDR;
        end
        ADDR: if (awvalid) state <= RESP;
        DATA: if (wvalid)  state <= RESP;
        RESP: begin
          awready <= 1'b0; wready <= 1'b0; bvalid <= 1'b1;
          if (bready) begin bvalid <= 1'b0; state <= IDLE; end
        end
      endcase
    end
  end
endmodule

