entries.rtl:
module ahb_slave(hclk, hresetn, hsel, htrans, hwrite, hsize, hready, hresp, state);
  input hclk, hresetn, hsel, hwrite;
  input [1:0] htrans;
  input [2:0] hsize;
  output reg hready;
  output reg hresp;
  output reg [1:0] state;
  parameter IDLE=2'd0, ACTIVE=2'd1, WAIT=2'd2, ERROR=2'd3;
  always @(posedge hclk or negedge hresetn) begin
    if (!hresetn) begin
      state <= IDLE; hready <= 1'b1; hresp <= 1'b0;
    end else begin
      case (state)
        IDLE:   if (hsel && (htrans != 2'b00)) begin
                  state <= ACTIVE; hready <= 1'b0;
                end
        ACTIVE: begin
                  if (hsize > 3'd2) begin state <= ERROR; hresp <= 1'b1; end
                  else              begin state <= WAIT; end
                end
        WAIT:   begin hready <= 1'b1; state <= IDLE; end
        ERROR:  begin hready <= 1'b1; hresp <= 1'b0; state <= IDLE; end
      endcase
    end
  end
endmodule

entries.coverage_model:
covergroup cg_wb_slave (ref logic cyc_i, stb_i, we_i, ack_o, err_o, ref logic [3:0] adr_i) @(posedge clk);
  cyc_cp : coverpoint cyc_i { bins idle = {0}; bins active = {1}; }
  stb_cp : coverpoint stb_i { bins idle = {0}; bins strobed = {1}; }
  we_cp  : coverpoint we_i  { bins read = {0}; bins write = {1}; }
  ack_cp : coverpoint ack_o { bins pending = {0}; bins acked = {1}; }
  err_cp : coverpoint err_o { bins ok = {0}; bins error = {1}; }
  adr_cp : coverpoint adr_i {
    bins mapped[]  = {[4'd0:4'd7]};
    bins unmapped  = {[4'd8:4'd15]};
  }
  qualify_cross : cross cyc_cp, stb_cp;
  adr_x_err     : cross adr_cp, err_cp;
  we_x_ack      : cross we_cp, ack_cp;
  ack_trans_cp : coverpoint ack_o {
    bins single_cycle_ack = (0 => 1 => 0);
  }
endgroup

entries.rtl:
module wishbone_slave(clk, rst, cyc_i, stb_i, we_i, adr_i, dat_i, dat_o, ack_o, err_o);
  input clk, rst, cyc_i, stb_i, we_i;
  input [3:0] adr_i;
  input [7:0] dat_i;
  output reg [7:0] dat_o;
  output reg ack_o, err_o;
  reg [7:0] mem [0:7];
  wire valid_access;
  assign valid_access = cyc_i && stb_i;
  always @(posedge clk) begin
    if (rst) begin
      ack_o <= 1'b0; err_o <= 1'b0;
    end else begin
      ack_o <= 1'b0; err_o <= 1'b0;
      if (valid_access && !ack_o) begin
        if (adr_i > 4'd7) begin
          err_o <= 1'b1;
        end else begin
          if (we_i) mem[adr_i[2:0]] <= dat_i;
          else      dat_o <= mem[adr_i[2:0]];
          ack_o <= 1'b1;
        end
      end
    end
  end
endmodule

entries.coverage_model:
covergroup cg_i2c_master (ref logic [2:0] state, ref logic [3:0] bitcnt, ref logic start, rw, sda_in, ack_err) @(posedge clk);
  state_cp : coverpoint state {
    bins idle  = {3'd0};
    bins start = {3'd1};
    bins addr  = {3'd2};
    bins ack1  = {3'd3};
    bins data  = {3'd4};
    bins ack2  = {3'd5};
    bins stop  = {3'd6};
    illegal_bins unused = {3'd7};
  }
  bitcnt_cp : coverpoint bitcnt {
    bins bit_pos[] = {[4'd0:4'd7]};
    illegal_bins bad = {[4'd8:4'd15]};
  }
  rw_cp : coverpoint rw {
    bins write_dir = {0};
    bins read_dir  = {1};
  }
  ack_cp : coverpoint ack_err {
    bins acked = {0};
    bins nacked= {1};
  }
  state_trans_cp : coverpoint state {
    bins full_write = (3'd0 => 3'd1 => 3'd2 => 3'd3 => 3'd4 => 3'd5 => 3'd6);
    bins early_stop = (3'd3 => 3'd6);
    bins restart    = (3'd6 => 3'd0 => 3'd1);
  }
  state_x_rw   : cross state_cp, rw_cp;
  state_x_ack  : cross state_cp, ack_cp;
  bitcnt_x_state : cross bitcnt_cp, state_cp;
endgroup

entries.rtl:
module i2c_master(clk, rst_n, start, rw, sda_in, state, bitcnt, ack_err, sda_out, scl);
  input clk, rst_n, start, rw, sda_in;
  output reg [2:0] state;
  output reg [3:0] bitcnt;
  output reg ack_err;
  output reg sda_out, scl;
  parameter IDLE=3'd0, START=3'd1, ADDR=3'd2, ACK1=3'd3, DATA=3'd4, ACK2=3'd5, STOP=3'd6;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state <= IDLE; bitcnt <= 4'd0; ack_err <= 1'b0; sda_out <= 1'b1; scl <= 1'b1;
    end else begin
      case (state)
        IDLE:  if (start) begin sda_out <= 1'b0; state <= START; end
        START: begin scl <= 1'b0; bitcnt <= 4'd7; state <= ADDR; end
        ADDR:  if (bitcnt == 4'd0) state <= ACK1;
               else bitcnt <= bitcnt - 4'd1;
        ACK1:  begin
                 ack_err <= sda_in;
                 bitcnt  <= 4'd7;
                 state   <= sda_in ? STOP : DATA;
               end
        DATA:  if (bitcnt == 4'd0) state <= ACK2;
               else bitcnt <= bitcnt - 4'd1;
        ACK2:  begin ack_err <= sda_in; state <= STOP; end
        STOP:  begin scl <= 1'b1; sda_out <= 1'b1; state <= IDLE; end
        default: state <= IDLE;
      endcase
    end
  end
endmodule

entries.coverage_model:
covergroup cg_spi_slave (ref logic [2:0] bitcnt, ref logic [7:0] rx_data, tx_data, ref logic cs_n, mosi, miso, done) @(posedge sclk);
  bitcnt_cp : coverpoint bitcnt {
    bins pos[] = {[0:7]};
  }
  cs_cp : coverpoint cs_n {
    bins selected   = {0};
    bins deselected = {1};
  }
  cs_trans_cp : coverpoint cs_n {
    bins begin_xfer  = (1 => 0);
    bins end_xfer    = (0 => 1);
  }
  mosi_cp : coverpoint mosi { bins zero_bit = {0}; bins one_bit = {1}; }
  miso_cp : coverpoint miso { bins zero_bit = {0}; bins one_bit = {1}; }
  rx_cp : coverpoint rx_data {
    bins all_zero = {8'h00};
    bins all_one  = {8'hFF};
    bins other    = default;
  }
  tx_cp : coverpoint tx_data {
    bins all_zero = {8'h00};
    bins all_one  = {8'hFF};
    bins other    = default;
  }
  done_cp : coverpoint done { bins partial = {0}; bins byte_done = {1}; }
  bitcnt_x_cs   : cross bitcnt_cp, cs_cp;
  mosi_x_bitcnt : cross mosi_cp, bitcnt_cp;
  tx_x_miso     : cross tx_cp, miso_cp;
endgroup

entries.rtl:
module spi_slave(sclk, rst_n, cs_n, mosi, tx_data, miso, rx_data, bitcnt, done);
  input sclk, rst_n, cs_n, mosi;
  input [7:0] tx_data;
  output miso;
  output reg [7:0] rx_data;
  output reg [2:0] bitcnt;
  output done;
  reg [7:0] shifter;
  assign miso = shifter[7];
  assign done = (bitcnt == 3'd7) && !cs_n;
  always @(posedge sclk or negedge rst_n) begin
    if (!rst_n) begin
      bitcnt <= 3'd0; rx_data <= 8'h00; shifter <= 8'h00;
    end else if (cs_n) begin
      bitcnt  <= 3'd0;
      shifter <= tx_data;
    end else begin
      rx_data <= {rx_data[6:0], mosi};
      shifter <= {shifter[6:0], 1'b0};
      bitcnt  <= bitcnt + 3'd1;
    end
  end
endmodule

entries.coverage_model:
covergroup cg_baud_gen (ref logic [11:0] divisor, cnt, ref logic en, tick, half_tick) @(posedge clk);
  divisor_cp : coverpoint divisor {
    bins minimum = {12'd0, 12'd1};
    bins fast    = {[12'd2:12'd15]};
    bins typical = {[12'd16:12'd2047]};
    bins slow    = {[12'd2048:12'd4094]};
    bins maximum = {12'd4095};
  }
  cnt_cp : coverpoint cnt {
    bins expired = {12'd0};
    bins running = {[12'd1:12'd4094]};
    bins reload  = {12'd4095};
  }
  en_cp : coverpoint en {
    bins stopped = {0};
    bins running = {1};
  }
  tick_cp      : coverpoint tick      { bins idle = {0}; bins firing = {1}; }
  half_tick_cp : coverpoint half_tick { bins idle = {0}; bins firing = {1}; }
  tick_trans_cp : coverpoint tick {
    bins single_pulse = (0 => 1 => 0);
  }
  divisor_x_tick : cross divisor_cp, tick_cp;
  en_x_tick      : cross en_cp, tick_cp;
endgroup

entries.rtl:
module uart_baud_gen(clk, rst_n, en, divisor, cnt, tick, half_tick);
  input clk, rst_n, en;
  input [11:0] divisor;
  output reg [11:0] cnt;
  output tick, half_tick;
  assign tick      = en && (cnt == 12'd0);
  assign half_tick = en && (cnt == (divisor >> 1));
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n)          cnt <= 12'd0;
    else if (!en)        cnt <= divisor;
    else if (cnt == 12'd0) cnt <= divisor;
    else                 cnt <= cnt - 12'd1;
  end
endmodule

entries.coverage_model:
covergroup cg_uart_parity (ref logic [1:0] mode, ref logic [7:0] data, ref logic par_bit, stop_bit, par_err, frame_err, err) @(posedge clk);
  mode_cp : coverpoint mode {
    bins no_parity   = {2'd0};
    bins even_parity = {2'd1};
    bins odd_parity  = {2'd2};
    bins reserved    = {2'd3};
  }
  data_cp : coverpoint data {
    bins all_zero = {8'h00};
    bins all_one  = {8'hFF};
    bins other    = default;
  }
  weight_cp : coverpoint (^data) {
    bins even_weight = {0};
    bins odd_weight  = {1};
  }
  stop_cp : coverpoint stop_bit {
    bins framing_bad = {0};
    bins framing_ok  = {1};
  }
  par_err_cp   : coverpoint par_err   { bins ok = {0}; bins mismatch = {1}; }
  frame_err_cp : coverpoint frame_err { bins ok = {0}; bins bad_stop = {1}; }
  err_cp       : coverpoint err       { bins clean = {0}; bins faulted = {1}; }
  mode_x_parerr   : cross mode_cp, par_err_cp;
  weight_x_parbit : cross weight_cp, par_bit;
  stop_x_frameerr : cross stop_cp, frame_err_cp;
endgroup

entries.rtl:
module uart_parity(clk, rst_n, valid, data, par_bit, stop_bit, mode, par_err, frame_err, err);
  input clk, rst_n, valid, par_bit, stop_bit;
  input [7:0] data;
  input [1:0] mode;
  output reg par_err, frame_err;
  output err;
  wire expected;
  assign expected = (mode == 2'd1) ? (^data) : ~(^data);
  assign err      = par_err | frame_err;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      par_err <= 1'b0; frame_err <= 1'b0;
    end else if (valid) begin
      par_err   <= (mode == 2'd0) ? 1'b0 : (par_bit != expected);
      frame_err <= (stop_bit != 1'b1);
    end
  end
endmodule

entries.coverage_model:
covergroup cg_manch_enc (ref logic din, phase, dout, en) @(posedge clk);
  din_cp : coverpoint din {
    bins bit_zero = {0};
    bins bit_one  = {1};
  }
  phase_cp : coverpoint phase {
    bins first_half  = {0};
    bins second_half = {1};
  }
  dout_cp : coverpoint dout {
    bins low  = {0};
    bins high = {1};
  }
  phase_trans_cp : coverpoint phase {
    bins toggle_up   = (0 => 1);
    bins toggle_down = (1 => 0);
  }
  dout_trans_cp : coverpoint dout {
    bins mid_bit_rise = (0 => 1);
    bins mid_bit_fall = (1 => 0);
  }
  din_x_phase : cross din_cp, phase_cp;
  din_x_dout  : cross din_cp, dout_cp;
  en_x_phase  : cross en, phase_cp;
endgroup

entries.rtl:
module manchester_enc(clk, rst_n, en, din, phase, dout);
  input clk, rst_n, en, din;
  output reg phase;
  output dout;
  assign dout = phase ? ~din : din;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n)  phase <= 1'b0;
    else if (en) phase <= ~phase;
  end
endmodule

entries.coverage_model:
covergroup cg_manch_dec (ref logic din, half, first_sample, dout, valid, violation, sync) @(posedge clk);
  half_cp : coverpoint half {
    bins sample_first  = {0};
    bins sample_second = {1};
  }
  dout_cp : coverpoint dout {
    bins bit_zero = {0};
    bins bit_one  = {1};
  }
  valid_cp : coverpoint valid {
    bins idle       = {0};
    bins bit_ready  = {1};
  }
  violation_cp : coverpoint violation {
    bins legal   = {0};
    bins illegal = {1};
  }
  sync_cp : coverpoint sync {
    bins unsynced = {0};
    bins synced   = {1};
  }
  sync_trans_cp : coverpoint sync {
    bins acquire = (0 => 1);
    bins lose    = (1 => 0);
  }
  valid_trans_cp : coverpoint valid {
    bins one_per_bit = (0 => 1 => 0);
  }
  half_x_din    : cross half_cp, din;
  sync_x_valid  : cross sync_cp, valid_cp;
  dout_x_valid  : cross dout_cp, valid_cp;
endgroup

entries.rtl:
module manchester_dec(clk, rst_n, din, sync, half, first_sample, dout, valid, violation);
  input clk, rst_n, din;
  output reg sync, half, first_sample;
  output reg dout;
  output reg valid, violation;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      sync <= 1'b0; half <= 1'b0; first_sample <= 1'b0;
      dout <= 1'b0; valid <= 1'b0; violation <= 1'b0;
    end else begin
      half  <= ~half;
      valid <= 1'b0;
      violation <= 1'b0;
      if (!half) begin
        first_sample <= din;
      end else begin
        if (first_sample == din) begin
          violation <= 1'b1;
          sync      <= 1'b0;
        end else begin
          dout  <= first_sample;
          valid <= 1'b1;
          sync  <= 1'b1;
        end
      end
    end
  end
endmodule

entries.coverage_model:
covergroup cg_disparity (ref logic [3:0] ones, ref logic rd, disp_err, valid) @(posedge clk);
  ones_cp : coverpoint ones {
    bins neg_two   = {4'd4};
    bins balanced  = {4'd5};
    bins pos_two   = {4'd6};
    bins illegal   = {[4'd0:4'd3], [4'd7:4'd10]};
  }
  rd_cp : coverpoint rd {
    bins negative = {0};
    bins positive = {1};
  }
  rd_trans_cp : coverpoint rd {
    bins flip_pos  = (0 => 1);
    bins flip_neg  = (1 => 0);
    bins hold_neg  = (0 => 0);
    bins hold_pos  = (1 => 1);
  }
  err_cp : coverpoint disp_err {
    bins ok    = {0};
    bins error = {1};
  }
  valid_cp : coverpoint valid { bins idle = {0}; bins symbol = {1}; }
  ones_x_rd  : cross ones_cp, rd_cp;
  ones_x_err : cross ones_cp, err_cp;
endgroup

entries.rtl:
module disparity_8b10b(clk, rst_n, valid, symbol, rd, disp_err);
  input clk, rst_n, valid;
  input [9:0] symbol;
  output reg rd;
  output reg disp_err;
  integer i;
  reg [3:0] ones;
  always @(*) begin
    ones = 4'd0;
    for (i = 0; i < 10; i = i + 1)
      if (symbol[i]) ones = ones + 4'd1;
  end
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      rd <= 1'b0; disp_err <= 1'b0;
    end else if (valid) begin
      case (ones)
        4'd5: begin rd <= rd;  disp_err <= 1'b0; end
        4'd4: begin rd <= 1'b0; disp_err <= (rd == 1'b0); end
        4'd6: begin rd <= 1'b1; disp_err <= (rd == 1'b1); end
        default: disp_err <= 1'b1;
      endcase
    end
  end
endmodule

entries.coverage_model:
covergroup cg_crc16 (ref logic [15:0] crc, ref logic din, fb, en, init) @(posedge clk);
  crc_cp : coverpoint crc {
    bins zero    = {16'h0000};
    bins seed    = {16'hFFFF};
    bins low     = {[16'h0001:16'h7FFF]};
    bins high    = {[16'h8000:16'hFFFE]};
  }
  din_cp : coverpoint din {
    bins bit_zero = {0};
    bins bit_one  = {1};
  }
  fb_cp : coverpoint fb {
    bins no_feedback = {0};
    bins feedback    = {1};
  }
  en_cp   : coverpoint en   { bins idle = {0}; bins shifting = {1}; }
  init_cp : coverpoint init { bins running = {0}; bins seeding = {1}; }
  crc_trans_cp : coverpoint crc {
    bins reseed = (16'h0000 => 16'hFFFF);
  }
  din_x_fb   : cross din_cp, fb_cp;
  en_x_init  : cross en_cp, init_cp;
  crc_x_fb   : cross crc_cp, fb_cp;
endgroup

entries.rtl:
module crc16_ccitt(clk, rst_n, init, en, din, crc);
  input clk, rst_n, init, en, din;
  output reg [15:0] crc;
  wire fb;
  assign fb = din ^ crc[15];
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n)      crc <= 16'hFFFF;
    else if (init)   crc <= 16'hFFFF;
    else if (en) begin
      crc[0]     <= fb;
      crc[4:1]   <= crc[3:0];
      crc[5]     <= crc[4] ^ fb;
      crc[11:6]  <= crc[10:5];
      crc[12]    <= crc[11] ^ fb;
      crc[15:13] <= crc[14:12];
    end
  end
endmodule

entries.coverage_model:
covergroup cg_ones_cksum (ref logic [15:0] sum, din, result, ref logic carry, en, clr) @(posedge clk);
  sum_cp : coverpoint sum {
    bins zero = {16'h0000};
    bins low  = {[16'h0001:16'h7FFF]};
    bins high = {[16'h8000:16'hFFFE]};
    bins max  = {16'hFFFF};
  }
  din_cp : coverpoint din {
    bins zero = {16'h0000};
    bins mid  = {[16'h0001:16'hFFFE]};
    bins max  = {16'hFFFF};
  }
  carry_cp : coverpoint carry {
    bins no_wrap = {0};
    bins wrapped = {1};
  }
  en_cp  : coverpoint en  { bins idle = {0}; bins accumulating = {1}; }
  clr_cp : coverpoint clr { bins normal = {0}; bins clearing = {1}; }
  result_cp : coverpoint result {
    bins zero = {16'h0000};
    bins max  = {16'hFFFF};
    bins mid  = {[16'h0001:16'hFFFE]};
  }
  din_x_carry : cross din_cp, carry_cp;
  en_x_clr    : cross en_cp, clr_cp;
  sum_x_result: cross sum_cp, result_cp;
endgroup

entries.rtl:
module ones_comp_cksum(clk, rst_n, clr, en, din, sum, result, carry);
  input clk, rst_n, clr, en;
  input [15:0] din;
  output reg [15:0] sum;
  output [15:0] result;
  output reg carry;
  wire [16:0] raw;
  assign raw    = {1'b0, sum} + {1'b0, din};
  assign result = ~sum;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n || clr) begin
      sum <= 16'h0000; carry <= 1'b0;
    end else if (en) begin
      sum   <= raw[15:0] + {15'b0, raw[16]};
      carry <= raw[16];
    end
  end
endmodule

entries.coverage_model:
covergroup cg_scrambler (ref logic [6:0] lfsr, ref logic din, dout, fb, load, bypass, en) @(posedge clk);
  lfsr_cp : coverpoint lfsr {
    bins all_zero = {7'h00};
    bins low      = {[7'h01:7'h3F]};
    bins high     = {[7'h40:7'h7E]};
    bins all_one  = {7'h7F};
  }
  fb_cp : coverpoint fb {
    bins fb_zero = {0};
    bins fb_one  = {1};
  }
  din_cp  : coverpoint din  { bins zero = {0}; bins one = {1}; }
  dout_cp : coverpoint dout { bins zero = {0}; bins one = {1}; }
  bypass_cp : coverpoint bypass {
    bins scrambling = {0};
    bins passthru   = {1};
  }
  load_cp : coverpoint load { bins running = {0}; bins seeding = {1}; }
  en_cp   : coverpoint en   { bins paused = {0}; bins shifting = {1}; }
  din_x_fb      : cross din_cp, fb_cp;
  bypass_x_dout : cross bypass_cp, dout_cp;
  load_x_en     : cross load_cp, en_cp;
endgroup

entries.rtl:
module scrambler(clk, rst_n, load, bypass, en, seed, din, dout, lfsr);
  input clk, rst_n, load, bypass, en, din;
  input [6:0] seed;
  output dout;
  output reg [6:0] lfsr;
  wire fb;
  assign fb   = lfsr[6] ^ lfsr[3];
  assign dout = bypass ? din : (din ^ fb);
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n)     lfsr <= 7'h7F;
    else if (load)  lfsr <= seed;
    else if (en)    lfsr <= {lfsr[5:0], fb};
  end
endmodule

entries.coverage_model:
covergroup cg_div_nonrest (ref logic [3:0] step, ref logic [7:0] quotient, div_r, ref logic signed [8:0] remainder, ref logic busy, done, div0, start) @(posedge clk);
  step_cp : coverpoint step {
    bins idle       = {4'd0};
    bins iterate[]  = {[4'd1:4'd8]};
    bins complete   = {4'd9};
    illegal_bins bad= {[4'd10:4'd15]};
  }
  rem_sign_cp : coverpoint remainder[8] {
    bins positive = {0};
    bins negative = {1};
  }
  quotient_cp : coverpoint quotient {
    bins zero = {8'h00};
    bins mid  = {[8'h01:8'hFE]};
    bins max  = {8'hFF};
  }
  divisor_cp : coverpoint div_r {
    bins zero = {8'h00};
    bins one  = {8'h01};
    bins mid  = {[8'h02:8'hFE]};
    bins max  = {8'hFF};
  }
  div0_cp : coverpoint div0 {
    bins ok       = {0};
    bins div_by_0 = {1};
  }
  step_trans_cp : coverpoint step {
    bins launch = (4'd0 => 4'd1);
    bins finish = (4'd8 => 4'd9);
  }
  step_x_sign     : cross step_cp, rem_sign_cp;
