entries.rtl:
module divider_nonrest(clk, rst_n, start, dividend, divisor, quotient, remainder, step, busy, done, div0);
  input clk, rst_n, start;
  input [7:0] dividend, divisor;
  output reg [7:0] quotient;
  output reg signed [8:0] remainder;
  output reg [3:0] step;
  output busy, done, div0;
  reg [7:0] div_r;
  assign busy = (step != 4'd0) && (step != 4'd9);
  assign done = (step == 4'd9);
  assign div0 = (div_r == 8'h00);
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      step <= 4'd0; quotient <= 8'h00; remainder <= 9'sd0;
    end else if (start) begin
      quotient  <= dividend;
      div_r     <= divisor;
      remainder <= 9'sd0;
      step      <= 4'd1;
    end else if (busy) begin
      if (remainder >= 9'sd0)
        remainder <= {remainder[7:0], quotient[7]} - {1'b0, div_r};
      else
        remainder <= {remainder[7:0], quotient[7]} + {1'b0, div_r};
      quotient <= {quotient[6:0], (remainder >= 9'sd0)};
      step     <= step + 4'd1;
    end
  end
endmodule

