module booth_mult(clk, rst_n, start, a, b, product, step, action, done);
  input clk, rst_n, start;
  input signed [7:0] a, b;
  output reg signed [15:0] product;
  output reg [2:0] step;
  output reg [1:0] action;
  output done;
  reg signed [7:0] mcand;
  reg [8:0] mplier;
  assign done = (step == 3'd4);
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      step <= 3'd0; product <= 16'sd0; action <= 2'd0;
    end else if (start) begin
      mcand   <= a;
      mplier  <= {b, 1'b0};
      product <= 16'sd0;
      step    <= 3'd1;
    end else if (step != 3'd0 && !done) begin
      case (mplier[1:0])
        2'b01: begin product <= product + (mcand <<< (2*(step-1))); action <= 2'd1; end
        2'b10: begin product <= product - (mcand <<< (2*(step-1))); action <= 2'd2; end
        default: action <= 2'd0;
      endcase
      mplier <= mplier >> 2;
      step   <= step + 3'd1;
    end
  end
endmodule

