module cordic_iter(clk, rst_n, start, angle_in, x, y, z, iter, busy, done, dir);
  input clk, rst_n, start;
  input signed [15:0] angle_in;
  output reg signed [15:0] x, y, z;
  output reg [2:0] iter;
  output busy, done;
  output dir;
  assign dir  = ~z[15];
  assign busy = (iter != 3'd0) && (iter != 3'd7);
  assign done = (iter == 3'd7);
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      iter <= 3'd0; x <= 16'sd0; y <= 16'sd0; z <= 16'sd0;
    end else if (start) begin
      x <= 16'sd9949; y <= 16'sd0; z <= angle_in; iter <= 3'd1;
    end else if (busy) begin
      if (dir) begin
        x <= x - (y >>> iter);
        y <= y + (x >>> iter);
        z <= z - 16'sd2949;
      end else begin
        x <= x + (y >>> iter);
        y <= y - (x >>> iter);
        z <= z + 16'sd2949;
      end
      iter <= iter + 3'd1;
    end
  end
endmodule

