entries.rtl:
module fixed_round(din, mode, dout, sat);
  input signed [11:0] din;
  input [1:0] mode;
  output reg signed [7:0] dout;
  output reg sat;
  wire [3:0] frac;
  wire signed [8:0] whole;
  reg signed [8:0] rounded;
  assign frac  = din[3:0];
  assign whole = din[11:3];
  always @(*) begin
    case (mode)
      2'd0: rounded = whole;
      2'd1: rounded = (frac >= 4'd8) ? (whole + 9'sd1) : whole;
      2'd2: rounded = (frac > 4'd8) ? (whole + 9'sd1) :
                      (frac == 4'd8) ? (whole + {8'd0, whole[0]}) : whole;
      default: rounded = whole;
    endcase
    sat  = (rounded > 9'sd127) || (rounded < -9'sd128);
    dout = sat ? (rounded[8] ? -8'sd128 : 8'sd127) : rounded[7:0];
  end
endmodule

