module dma_ctrl(clk, rst_n, start, abort, ack, length, state, remaining, irq, busy);
  input clk, rst_n, start, abort, ack;
  input [7:0] length;
  output reg [2:0] state;
  output reg [7:0] remaining;
  output reg irq;
  output busy;
  parameter IDLE=3'd0, FETCH=3'd1, READ=3'd2, WRITE=3'd3, DONE=3'd4, ABORT=3'd5;
  assign busy = (state != IDLE) && (state != DONE);
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state <= IDLE; remaining <= 8'd0; irq <= 1'b0;
    end else if (abort && busy) begin
      state <= ABORT;
    end else begin
      case (state)
        IDLE:  if (start) begin remaining <= length; state <= FETCH; irq <= 1'b0; end
        FETCH: state <= READ;
        READ:  if (ack) state <= WRITE;
        WRITE: begin
                 remaining <= remaining - 8'd1;
                 state <= (remaining == 8'd1) ? DONE : READ;
               end
        DONE:  begin irq <= 1'b1; state <= IDLE; end
        ABORT: begin irq <= 1'b1; state <= IDLE; end
        default: state <= IDLE;
      endcase
    end
  end
endmodule

