  }
  depth_cp : coverpoint depth {
    bins idle    = {3'd0};
    bins nested[]= {[3'd1:3'd4]};
    illegal_bins overflow = {[3'd5:3'd7]};
  }
  depth_trans_cp : coverpoint depth {
    bins preempt = (3'd1 => 3'd2);
