entries.rtl:
module intr_nested(clk, rst_n, irq, mask, ack, active_level, depth, taken);
  input clk, rst_n, ack;
  input [3:0] irq, mask;
  output reg [1:0] active_level;
  output reg [2:0] depth;
  output taken;
  wire [3:0] pending;
  reg [1:0] highest;
  integer i;
  assign pending = irq & ~mask;
  assign taken   = (|pending) && ((depth == 3'd0) || (highest > active_level));
  always @(*) begin
    highest = 2'd0;
    for (i = 0; i < 4; i = i + 1)
      if (pending[i]) highest = i[1:0];
  end
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      active_level <= 2'd0; depth <= 3'd0;
    end else if (taken && (depth != 3'd4)) begin
      active_level <= highest;
      depth        <= depth + 3'd1;
    end else if (ack && (depth != 3'd0)) begin
      depth <= depth - 3'd1;
    end
  end
endmodule

