entries.rtl:
module power_fsm(clk, rst_n, sleep_req, wake, deep, timer_done, state, clk_en, pwr_en);
  input clk, rst_n, sleep_req, wake, deep, timer_done;
  output reg [2:0] state;
  output clk_en, pwr_en;
  parameter ACTIVE=3'd0, IDLE_S=3'd1, SLEEP=3'd2, DEEP=3'd3, RETENTION=3'd4, WAKEUP=3'd5;
  assign clk_en = (state == ACTIVE) || (state == WAKEUP);
  assign pwr_en = (state != DEEP) && (state != RETENTION);
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) state <= ACTIVE;
    else begin
      case (state)
        ACTIVE:    if (sleep_req) state <= IDLE_S;
        IDLE_S:    if (wake) state <= ACTIVE;
                   else if (sleep_req) state <= deep ? DEEP : SLEEP;
        SLEEP:     if (wake) state <= WAKEUP;
        DEEP:      if (wake) state <= WAKEUP;
                   else if (sleep_req) state <= RETENTION;
        RETENTION: if (wake) state <= WAKEUP;
        WAKEUP:    if (timer_done) state <= ACTIVE;
        default:   state <= ACTIVE;
      endcase
    end
  end
endmodule

