module cache_ctrl(clk, rst_n, req, hit, dirty, mem_ack, state, wb_req, fill_req);
  input clk, rst_n, req, hit, dirty, mem_ack;
  output reg [2:0] state;
  output wb_req, fill_req;
  parameter IDLE=3'd0, LOOKUP=3'd1, HIT_S=3'd2, WRITEBACK=3'd3, FILL=3'd4, DONE=3'd5;
  assign wb_req   = (state == WRITEBACK);
  assign fill_req = (state == FILL);
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) state <= IDLE;
    else begin
      case (state)
        IDLE:      if (req) state <= LOOKUP;
        LOOKUP:    state <= hit ? HIT_S : (dirty ? WRITEBACK : FILL);
        HIT_S:     state <= DONE;
        WRITEBACK: if (mem_ack) state <= FILL;
        FILL:      if (mem_ack) state <= DONE;
        DONE:      state <= IDLE;
        default:   state <= IDLE;
      endcase
    end
  end
endmodule

