module retry_timeout(clk, rst_n, start, done_ok, state, retries, timer, fail);
  input clk, rst_n, start, done_ok;
  output reg [1:0] state;
  output reg [1:0] retries;
  output reg [3:0] timer;
  output fail;
  parameter IDLE=2'd0, WAIT=2'd1, RETRY=2'd2, FAIL=2'd3;
  assign fail = (state == FAIL);
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state <= IDLE; retries <= 2'd0; timer <= 4'd0;
    end else begin
      case (state)
        IDLE:  if (start) begin state <= WAIT; timer <= 4'd15; retries <= 2'd0; end
        WAIT:  if (done_ok) begin state <= IDLE; retries <= 2'd0; end
               else if (timer == 4'd0) state <= RETRY;
               else timer <= timer - 4'd1;
        RETRY: if (retries == 2'd3) state <= FAIL;
               else begin
                 retries <= retries + 2'd1;
                 timer   <= 4'd15;
                 state   <= WAIT;
               end
        FAIL:  if (!start) state <= IDLE;
      endcase
    end
  end
endmodule

entries.coverage_model:
covergroup cg_bist (ref logic [2:0] state, ref logic [3:0] addr, ref logic run, abort, data_match, fail, pass) @(posedge clk);
  state_cp : coverpoint state {
    bins idle   = {3'd0};
    bins write0 = {3'd1};
    bins read0  = {3'd2};
    bins write1 = {3'd3};
    bins read1  = {3'd4};
    bins done   = {3'd5};
    illegal_bins unused = {[3'd6:3'd7]};
  }
  addr_cp : coverpoint addr {
    bins first = {4'd0};
    bins mid   = {[4'd1:4'd14]};
    bins last  = {4'd15};
  }
  state_trans_cp : coverpoint state {
    bins full_run = (3'd1 => 3'd2 => 3'd3 => 3'd4 => 3'd5);
    bins start    = (3'd0 => 3'd1);
    bins abort    = (3'd2 => 3'd0);
    bins finish   = (3'd5 => 3'd0);
  }
  addr_trans_cp : coverpoint addr {
    bins sweep_wrap = (4'd15 => 4'd0);
  }
  match_cp : coverpoint data_match {
    bins mismatch = {0};
    bins match    = {1};
  }
  fail_cp : coverpoint fail { bins clean = {0}; bins failed = {1}; }
  pass_cp : coverpoint pass { bins not_passed = {0}; bins passed = {1}; }
  state_x_addr  : cross state_cp, addr_cp;
  state_x_match : cross state_cp, match_cp;
  fail_x_pass   : cross fail_cp, pass_cp {
    illegal_bins both = binsof(fail_cp.failed) && binsof(pass_cp.passed);
  }
endgroup

entries.rtl:
module bist_ctrl(clk, rst_n, run, abort, data_match, state, addr, fail, pass);
  input clk, rst_n, run, abort, data_match;
  output reg [2:0] state;
  output reg [3:0] addr;
  output reg fail;
  output pass;
  parameter IDLE=3'd0, WRITE0=3'd1, READ0=3'd2, WRITE1=3'd3, READ1=3'd4, DONE=3'd5;
  assign pass = (state == DONE) && !fail;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state <= IDLE; addr <= 4'd0; fail <= 1'b0;
    end else if (abort) begin
      state <= IDLE; addr <= 4'd0;
    end else begin
      case (state)
        IDLE:   if (run) begin state <= WRITE0; addr <= 4'd0; fail <= 1'b0; end
        WRITE0: if (addr == 4'd15) begin state <= READ0; addr <= 4'd0; end
                else addr <= addr + 4'd1;
        READ0:  begin
                  if (!data_match) fail <= 1'b1;
                  if (addr == 4'd15) begin state <= WRITE1; addr <= 4'd0; end
                  else addr <= addr + 4'd1;
                end
        WRITE1: if (addr == 4'd15) begin state <= READ1; addr <= 4'd0; end
                else addr <= addr + 4'd1;
        READ1:  begin
                  if (!data_match) fail <= 1'b1;
                  if (addr == 4'd15) state <= DONE;
                  else addr <= addr + 4'd1;
                end
        DONE:   state <= IDLE;
        default: state <= IDLE;
      endcase
    end
  end
endmodule

