`timescale 1ns/1ps
module shift_reg_coverage (
  input logic       clk,
  input logic       rst_n,
  input logic       load,
  input logic       shift_en,
  input logic       din,
  input logic [7:0] parallel_in,
  input logic [7:0] dout,
  input logic       serial_out
);

  covergroup shift_reg_coverage_cg @(posedge clk);
    option.per_instance = 1;

    // Cover `rst_n` being asserted (0) or deasserted (1).
    rst_n_cp : coverpoint rst_n {
      bins asserted   = {0};
      bins deasserted = {1};
    }

    // Cover `load` control signal.
    load_cp : coverpoint load {
      bins active   = {1};
      bins inactive = {0};
    }

    // Cover `shift_en` control signal.
    shift_en_cp : coverpoint shift_en {
      bins active   = {1};
      bins inactive = {0};
    }

    // Cover `din` (serial input) values.
    din_cp : coverpoint din {
      bins zero = {0};
      bins one  = {1};
    }

    // Cover `parallel_in` values.
    // RTL shows `parallel_in` can be any 8-bit value.
    parallel_in_cp : coverpoint parallel_in {
      bins all_zero  = {8'h00};
      bins all_one   = {8'hFF};
      bins mid_range = {[8'h01:8'hFE]};
    }

    // Cover `dout` (register output) values.
    // RTL shows `dout` can be 8'h00 on reset, or `parallel_in`, or shifted values.
    dout_cp : coverpoint dout {
      bins all_zero = {8'h00};
      bins all_one  = {8'hFF};
      bins other    = default;
    }

    // Cover `serial_out` (MSB of register) values.
    serial_out_cp : coverpoint serial_out {
      bins zero = {0};
      bins one  = {1};
    }

    // Cross `load` and `shift_en` to cover control signal interactions.
    // This covers:
    // - Register being parallel loaded (load=1, shift_en=0)
    // - Register shifting (load=0, shift_en=1)
    // - Load takes priority (load=1, shift_en=1)
    // - Register holds (load=0, shift_en=0)
    load_x_shift_en_x : cross load_cp, shift_en_cp;

    // Cross `shift_en` and `din` to cover shifting in a one and a zero.
    // Ignore bins where `shift_en` is inactive, as `din` has no effect on shifting then.
    shift_en_x_din_x : cross shift_en_cp, din_cp {
      ignore_bins no_shift = binsof(shift_en_cp.inactive);
    }

    // Cross `rst_n` and `shift_en` to cover reset asserted while a shift is in progress.
    rst_n_x_shift_en_x : cross rst_n_cp, shift_en_cp;

    // Cross `din` and `serial_out` to cover the input/output activity during shifts.
    // This helps cover a bit being shifted through the register, by observing
    // the input and the final output bit when shifting is enabled.
    // FIX: The `iff` condition for a cross must be part of the cross declaration itself,
    // not inside the cross's body (i.e., not within the curly braces `{}`).
    din_x_serial_out_x : cross din_cp, serial_out_cp iff (shift_en);

  endgroup

  shift_reg_coverage_cg cg_inst = new();

  // Report the covergroup score directly from the simulator, so the
  // number does not depend on the coverage database or IMC's flags.
  final begin
    $display("SV_FUNCTIONAL_COVERAGE: %0.4f", $get_coverage());
    $display("SV_CG_INST_COVERAGE: %0.4f", cg_inst.get_inst_coverage());
  end

endmodule

entries.rtl:
// 8-bit shift register with parallel load. Tests sequential data movement and
// the interaction of two control signals that compete for the same register.
module shift_reg (clk, rst_n, load, shift_en, din, parallel_in, dout, serial_out);
    input        clk, rst_n, load, shift_en, din;
    input  [7:0] parallel_in;
    output [7:0] dout;
    output       serial_out;

    reg [7:0] shift_data;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)          shift_data <= 8'd0;
        else if (load)       shift_data <= parallel_in;
        else if (shift_en)   shift_data <= {shift_data[6:0], din};
    end

    assign dout       = shift_data;
    assign serial_out = shift_data[7];
endmodule

entries.coverage_model:
`timescale 1ns/1ps
module fifo_coverage (
  input logic clk,
  input logic rst_n,
  input logic wr_en,
  input logic rd_en,
  input logic [7:0] din,
  input logic full,
  input logic empty,
  input logic [3:0] count
);

  covergroup fifo_coverage_cg @(posedge clk);
    option.per_instance = 1;

    // RTL analysis for 'count':
    // The 'count' signal is declared [3:0], but the FIFO depth is 8.
    // The 'full' flag is asserted when count == 4'd8.
    // The 'empty' flag is asserted when count == 4'd0.
    // The 'count' value is reset to 0, increments by 1 (max 8), and decrements by 1 (min 0).
    // Therefore, 'count' will only ever range from 0 to 8. Values 9-15 are unreachable.
    count_cp : coverpoint count {
      bins empty_c   = {0};
      bins almost_e  = {1};
      bins mid       = {[2:7]}; // Occupancy levels between almost empty and full
      bins full_c    = {8};
      illegal_bins overflow = {[9:15]}; // Values 9-15 are unreachable for a FIFO of depth 8
    }

    // RTL analysis for 'wr_en': Single bit input.
    wr_en_cp : coverpoint wr_en {
      bins idle  = {0};
      bins write = {1};
    }

    // RTL analysis for 'rd_en': Single bit input.
    rd_en_cp : coverpoint rd_en {
      bins idle = {0};
      bins read = {1};
    }

    // RTL analysis for 'full': Single bit output, derived from 'count'.
    full_cp : coverpoint full {
      bins not_full = {0};
      bins is_full  = {1};
    }

    // RTL analysis for 'empty': Single bit output, derived from 'count'.
    empty_cp : coverpoint empty {
      bins not_empty = {0};
      bins is_empty  = {1};
    }

    // RTL analysis for 'din': 8-bit input.
    // Requirement: "Cover the data input at its minimum, maximum and mid-range values"
    din_cp : coverpoint din {
      bins min_val = {0};
      bins mid_val = {[1:254]}; // Covers the range between min and max
      bins max_val = {255};
    }

    // RTL analysis for 'rst_n': Single bit input (active low reset).
    rst_n_cp : coverpoint rst_n {
      bins asserted   = {0}; // Reset is active
      bins deasserted = {1}; // Reset is inactive
    }

    // Requirement: "Cover the FIFO becoming completely full"
    // RTL analysis: count transitions from 7 to 8 when a write occurs and FIFO is not full.
    // The 'iff' condition ensures this transition is only counted when a write is the cause.
    count_fill_cp : coverpoint count iff (wr_en && !full && !rd_en) {
      bins fill_up = (7 => 8);
    }

    // Requirement: "Cover the FIFO becoming completely empty"
    // RTL analysis: count transitions from 1 to 0 when a read occurs and FIFO is not empty.
    // The 'iff' condition ensures this transition is only counted when a read is the cause.
    count_drain_cp : coverpoint count iff (rd_en && !empty && !wr_en) {
      bins drain_out = (1 => 0);
    }

    // Requirement: "Cover the cross of the write enable against the read enable"
    wr_en_x_rd_en_x : cross wr_en_cp, rd_en_cp;

    // Requirement: "Cover the cross of each enable against the full and empty flags"
    wr_en_x_full_x  : cross wr_en_cp, full_cp;
    rd_en_x_empty_x : cross rd_en_cp, empty_cp;

    // Requirement: "Cover a simultaneous read and write while the FIFO is partially filled,
    // so the occupancy stays unchanged."
    // This requires wr_en=1, rd_en=1, and count to be in the range [1:7].
    simul_rw_x_count_x : cross wr_en_cp, rd_en_cp, count_cp {
      // Prune combinations where simultaneous R/W occurs when FIFO is empty or full.
      // In these cases, count would change (write rejected if full, read rejected if empty).
      // The requirement specifies "partially filled" and "occupancy stays unchanged".
      ignore_bins empty_or_full_rw = binsof(wr_en_cp.write) && binsof(rd_en_cp.read) &&
                                     (binsof(count_cp.empty_c) || binsof(count_cp.full_c));
    }

    // Requirement: "Cover the reset asserted while the FIFO holds data."
    // This corresponds to the condition (rst_n == 0 && empty == 0).
    // At the posedge clk sampling event, if rst_n is 0, the 'count' register is updated to 0.
    // However, 'empty' is a combinational output of 'count'.
    // Therefore, at the exact posedge clk, 'rst_n' can be 0, and 'empty' can still be 0
    // (reflecting the 'count' value *before* the current clock edge's update).
    // This makes the bin (rst_n=0, empty=0) reachable.
    rst_n_x_empty_x : cross rst_n_cp, empty_cp;

  endgroup

  fifo_coverage_cg cg_inst = new();

  // Report the covergroup score directly from the simulator, so the
  // number does not depend on the coverage database or IMC's flags.
  final begin
    $display("SV_FUNCTIONAL_COVERAGE: %0.4f", $get_coverage());
    $display("SV_CG_INST_COVERAGE: %0.4f", cg_inst.get_inst_coverage());
  end
endmodule

entries.rtl:
module fifo (clk, rst_n, wr_en, rd_en, din, dout, full, empty, count);
    input             clk;
    input             rst_n;
    input             wr_en;
    input             rd_en;
    input      [7:0]  din;
    output reg [7:0]  dout;
    output            full;
    output            empty;
    output reg [3:0]  count;

    reg [7:0] mem [0:7];
    reg [2:0] wptr, rptr;

    assign full  = (count == 4'd8);
    assign empty = (count == 4'd0);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wptr  <= 3'd0;
            rptr  <= 3'd0;
            count <= 4'd0;
            dout  <= 8'd0;
        end else begin
            if (wr_en && !full) begin
                mem[wptr] <= din;
                wptr      <= wptr + 3'd1;
            end
            if (rd_en && !empty) begin
                dout <= mem[rptr];
                rptr <= rptr + 3'd1;
            end
            case ({wr_en && !full, rd_en && !empty})
                2'b10:   count <= count + 4'd1;
                2'b01:   count <= count - 4'd1;
                default: count <= count;
            endcase
        end
    end
endmodule

entries.coverage_model:
`timescale 1ns/1ps
module counter_coverage (
  input logic       clk,
  input logic       rst_n,
  input logic       en,
  input logic [3:0] count
);

  covergroup counter_coverage_cg @(posedge clk);
    option.per_instance = 1;

    // Counter range is 0 to 15 as per RTL (4-bit unsigned).
    count_cp : coverpoint count {
      bins zero = {4'h0};
      bins low  = {[4'h1:4'h7]};
      bins high = {[4'h8:4'hE]};
      bins max  = {4'hF}; // 15
    }

    en_cp : coverpoint en {
      bins disabled = {0};
      bins enabled  = {1};
    }

    rst_n_cp : coverpoint rst_n {
      bins asserted   = {0};
      bins deasserted = {1};
    }

    // Cover the counter reaching its maximum value (15) and wrapping around to 0
    // on the next *enabled* clock edge.
    // This coverpoint contains transition bins and must not appear in a cross.
    count_wrap_cp : coverpoint count iff (en) {
      bins wrap = (4'hF => 4'h0); // 15 => 0
    }

    // Cover the counter holding its value when en is *deasserted*,
    // including holding at 0 and holding at 15.
    // This coverpoint contains transition bins and must not appear in a cross.
    count_hold_cp : coverpoint count iff (!en) {
      bins hold_zero = (4'h0 => 4'h0);
      bins hold_max  = (4'hF => 4'hF); // 15 => 15
    }

    // Cover an asynchronous reset asserted both while the counter is counting (en=1)
    // and while it is held (en=0).
    rst_n_x_en : cross rst_n_cp, en_cp;

    // Cover an asynchronous reset asserted while the counter is in various states.
    // When rst_n is asserted (0), the RTL forces 'count' to 0.
    // Therefore, any combination of rst_n.asserted with count != 0 is unreachable
    // *during* reset and must be pruned.
    rst_n_x_count : cross rst_n_cp, count_cp {
      ignore_bins reset_active_non_zero = binsof(rst_n_cp.asserted) && !binsof(count_cp.zero);
    }

  endgroup

  counter_coverage_cg cg_inst = new();

  // Report the covergroup score directly from the simulator, so the
  // number does not depend on the coverage database or IMC's flags.
  final begin
    $display("SV_FUNCTIONAL_COVERAGE: %0.4f", $get_coverage());
    $display("SV_CG_INST_COVERAGE: %0.4f", cg_inst.get_inst_coverage());
  end

endmodule

entries.rtl:
module counter (
    input  wire       clk,
    input  wire       rst_n,
    input  wire       en,
    output reg  [3:0] count
);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            count <= 4'b0000;
        else if (en)
            count <= count + 1'b1;
    end

endmodule

entries.coverage_model:
`timescale 1ns/1ps
module fsm_traffic_coverage (
  input logic clk,
  input logic rst_n,
  input logic sensor,
  input logic red,
  input logic yellow,
  input logic green
);

  // Local parameters for inferred states, matching DUT's internal states
  // S_RED = 2'd0, S_GREEN = 2'd1, S_YELLOW = 2'd2 from DUT's localparams.
  localparam S_RED = 2'd0;
  localparam S_GREEN = 2'd1;
  localparam S_YELLOW = 2'd2;
  // S_INVALID (2'd3) is used when the outputs (red, yellow, green) are not mutually exclusive
  // or when all are off, indicating an illegal state for the traffic light.
  localparam S_INVALID = 2'd3;

  // ALL declarations go at the TOP of a begin...end block, before any statement.
  // These are module-level declarations.
  logic [1:0] current_state_inferred;
  logic [1:0] prev_state_inferred;

  // Infer the current state from the DUT's output ports.
  // This assignment is continuous and not within a begin...end block.
  assign current_state_inferred = red ? S_RED : (green ? S_GREEN : (yellow ? S_YELLOW : S_INVALID));

  // Capture the previous state on the positive edge of the clock.
  always @(posedge clk) begin
    // No declarations needed inside this begin...end block.
    prev_state_inferred <= current_state_inferred;
  end

  covergroup fsm_traffic_coverage_cg @(posedge clk);
    option.per_instance = 1;

    // Requirement: "Cover every state of the traffic light controller: red, green and yellow."
    // Bin boundaries derived from RTL: S_RED (2'd0), S_GREEN (2'd1), S_YELLOW (2'd2).
    // S_INVALID (2'd3) is an illegal state, covering the mutual exclusivity requirement.
    state_cp : coverpoint current_state_inferred {
      bins red_s    = {S_RED};
      bins green_s  = {S_GREEN};
      bins yellow_s = {S_YELLOW};
      // Requirement: "Confirm the three output lights are mutually exclusive: exactly one is on at any time."
      // If current_state_inferred is S_INVALID (2'd3), it means the outputs are not mutually exclusive.
      illegal_bins invalid_state = {S_INVALID};
    }

    // Requirement: "Cover the sensor asserted and deasserted in each state." (partially covered here)
    // This coverpoint captures the sensor's value.
    sensor_cp : coverpoint sensor {
      bins sensor_off = {0};
      bins sensor_on  = {1};
    }

    // Requirement: "Cover the red state being held because the sensor is inactive even though the timer has expired"
    // In the RTL, if `state == S_RED` and `sensor == 0`, the state will always hold,
    // regardless of the timer value. The `iff (sensor == 0)` condition captures this.
    // This coverpoint contains transition bins and must not appear in a cross.
    red_hold_sensor_inactive_cp : coverpoint current_state_inferred iff (sensor == 0) {
      bins hold_red_sensor_off = (S_RED => S_RED);
    }

    // Requirement: "and cover it being held because the timer has not yet expired."
    // In the RTL, if `state == S_RED` and `sensor == 1`, but the state holds,
    // it implies `timer < 4'd5`. The `iff (sensor == 1)` condition captures this.
    // This coverpoint contains transition bins and must not appear in a cross.
    red_hold_timer_not_expired_cp : coverpoint current_state_inferred iff (sensor == 1) {
      bins hold_red_timer_not_exp = (S_RED => S_RED);
    }

    // Requirement: "Cover every legal transition between them: red to green"
    // In the RTL, this transition occurs when `state == S_RED`, `sensor == 1`, and `timer >= 4'd5`.
    // The `iff (sensor == 1)` captures the observable condition for this transition.
    // This coverpoint contains transition bins and must not appear in a cross.
    red_to_green_cp : coverpoint current_state_inferred iff (sensor == 1) {
      bins red_to_green = (S_RED => S_GREEN);
    }

    // Requirement: "Cover every legal transition between them: green to yellow"
    // In the RTL, this transition occurs when `state == S_GREEN` and `timer >= 4'd8`.
    // There is no `sensor` condition for this transition.
    // This coverpoint contains transition bins and must not appear in a cross.
    green_to_yellow_cp : coverpoint current_state_inferred {
      bins green_to_yellow = (S_GREEN => S_YELLOW);
    }

    // Requirement: "Cover every legal transition between them: yellow back to red"
    // In the RTL, this transition occurs when `state == S_YELLOW` and `timer >= 4'd2`.
    // There is no `sensor` condition for this transition.
    // This coverpoint contains transition bins and must not appear in a cross.
    yellow_to_red_cp : coverpoint current_state_inferred {
      bins yellow_to_red = (S_YELLOW => S_RED);
    }

    // Requirement: "Cover the sensor asserted and deasserted in each state."
    // This cross combines the state and sensor coverpoints.
    // Pruning: The 'invalid_state' bin from state_cp is automatically excluded from the cross.
    state_x_sensor_x : cross state_cp, sensor_cp;

  endgroup

  fsm_traffic_coverage_cg cg_inst = new();

  // Report the covergroup score directly from the simulator, so the
  // number does not depend on the coverage database or IMC's flags.
  final begin
    $display("SV_FUNCTIONAL_COVERAGE: %0.4f", $get_coverage());
    $display("SV_CG_INST_COVERAGE: %0.4f", cg_inst.get_inst_coverage());
  end

endmodule

entries.rtl:
// Traffic light FSM. Tests STATE and TRANSITION coverage -- the thing
// covergroups exist for, and which none of the designs tested so far exercise.
module fsm_traffic (clk, rst_n, sensor, red, yellow, green);
    input  clk, rst_n, sensor;
    output reg red, yellow, green;

    localparam S_RED = 2'd0, S_GREEN = 2'd1, S_YELLOW = 2'd2;

    reg [1:0] state;
    reg [3:0] timer;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S_RED;
            timer <= 4'd0;
        end else begin
            case (state)
                S_RED: begin
                    if (timer >= 4'd5 && sensor) begin
                        state <= S_GREEN; timer <= 4'd0;
                    end else timer <= timer + 4'd1;
                end
                S_GREEN: begin
                    if (timer >= 4'd8) begin
                        state <= S_YELLOW; timer <= 4'd0;
                    end else timer <= timer + 4'd1;
                end
                S_YELLOW: begin
                    if (timer >= 4'd2) begin
                        state <= S_RED; timer <= 4'd0;
                    end else timer <= timer + 4'd1;
                end
                default: state <= S_RED;
            endcase
        end
    end

    always @(*) begin
        red    = (state == S_RED);
        yellow = (state == S_YELLOW);
        green  = (state == S_GREEN);
    end
endmodule

entries.coverage_model:
`timescale 1ns/1ps
module fifo_coverage (
  input logic       clk,
  input logic       rst_n,
  input logic       wr_en,
  input logic       rd_en,
  input logic [7:0] din,
  input logic [7:0] dout,
  input logic       full,
  input logic       empty,
  input logic [3:0] count
);

  covergroup fifo_coverage_cg @(posedge clk);
    option.per_instance = 1;

    // RTL analysis for 'count':
    // The 'count' signal is declared [3:0], but the FIFO depth is 8.
    // The 'full' flag is asserted when count == 4'd8.
    // The 'empty' flag is asserted when count == 4'd0.
    // The 'count' value is reset to 0, increments by 1 (max 8), and decrements by 1 (min 0).
    // Therefore, 'count' will only ever range from 0 to 8. Values 9-15 are unreachable.
    count_cp : coverpoint count {
      bins empty_c    = {0};
      bins almost_e   = {1};
      bins mid_range  = {[2:7]}; // Occupancy levels between almost empty and full
      bins full_c     = {8};
      illegal_bins overflow = {[9:15]}; // Values 9-15 are unreachable for a FIFO of depth 8
      bins not_empty_c = {[1:8]}; // Helper bin for crosses, represents count > 0
    }

    // RTL analysis for 'wr_en': Single bit input.
    wr_en_cp : coverpoint wr_en {
      bins idle_wr  = {0};
      bins write_en = {1};
    }

    // RTL analysis for 'rd_en': Single bit input.
    rd_en_cp : coverpoint rd_en {
      bins idle_rd = {0};
      bins read_en = {1};
    }

    // RTL analysis for 'din': 8-bit input.
    // Requirement: "Cover the data input at its minimum, maximum and mid-range values"
    din_cp : coverpoint din {
      bins min_val = {8'h00};
      bins mid_val = {[8'h01:8'hFE]};
      bins max_val = {8'hFF};
    }

    // RTL analysis for 'rst_n': Active low reset.
    rst_n_cp : coverpoint rst_n {
      bins active_rst   = {0};
      bins inactive_rst = {1};
    }

    // RTL analysis for 'full': Output flag, derived from count.
    full_cp : coverpoint full {
      bins not_full_flag = {0};
      bins is_full_flag  = {1};
    }

    // RTL analysis for 'empty': Output flag, derived from count.
    empty_cp : coverpoint empty {
      bins not_empty_flag = {0};
      bins is_empty_flag  = {1};
    }

    // Requirement: "Cover a simultaneous read and write while the FIFO is partially filled,
    // so the occupancy stays unchanged."
    // This is a transition where count goes from X to X, under specific conditions.
    // Transition bins must use constants or constant ranges and cannot be part of a cross.
    // The original error was using a bin name 'mid_range' in a transition bin, which is not allowed.
    count_hold_t_cp : coverpoint count iff (wr_en && !full && rd_en && !empty) {
      bins hold_mid = ([2:7] => [2:7]); // Corrected: use constant range instead of bin name
    }

    // Requirement: "Cover a write attempted while the FIFO is full"
    wr_en_full_x : cross wr_en_cp, full_cp {
      bins write_when_full = binsof(wr_en_cp.write_en) && binsof(full_cp.is_full_flag);
    }

    // Requirement: "Cover a read attempted while it is empty"
    rd_en_empty_x : cross rd_en_cp, empty_cp {
      bins read_when_empty = binsof(rd_en_cp.read_en) && binsof(empty_cp.is_empty_flag);
    }

    // Requirement: "Cover the cross of the write enable against the read enable"
    wr_rd_x : cross wr_en_cp, rd_en_cp;

    // Requirement: "and the cross of each enable against the full and empty flags."
    // wr_en_full_x already covers wr_en vs full.
    wr_en_empty_x : cross wr_en_cp, empty_cp;
    rd_en_full_x  : cross rd_en_cp, full_cp;
    // rd_en_empty_x already covers rd_en vs empty.

    // Requirement: "Cover the reset asserted while the FIFO holds data."
    // When rst_n is active (0) at posedge clk, 'count' is sampled *before* the non-blocking update.
    // Therefore, 'count' can be non-zero at the sampling instant if the FIFO held data prior to reset.
    rst_n_data_x : cross rst_n_cp, count_cp {
      bins reset_with_data = binsof(rst_n_cp.active_rst) && binsof(count_cp.not_empty_c);
    }

  endgroup

  fifo_coverage_cg cg_inst = new();

  // Report the covergroup score directly from the simulator, so the
  // number does not depend on the coverage database or IMC's flags.
  final begin
    $display("SV_FUNCTIONAL_COVERAGE: %0.4f", $get_coverage());
    $display("SV_CG_INST_COVERAGE: %0.4f", cg_inst.get_inst_coverage());
  end
endmodule

entries.rtl:
module fifo (clk, rst_n, wr_en, rd_en, din, dout, full, empty, count);
    input             clk;
    input             rst_n;
    input             wr_en;
    input             rd_en;
    input      [7:0]  din;
    output reg [7:0]  dout;
    output            full;
    output            empty;
    output reg [3:0]  count;

    reg [7:0] mem [0:7];
    reg [2:0] wptr, rptr;

    assign full  = (count == 4'd8);
    assign empty = (count == 4'd0);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wptr  <= 3'd0;
            rptr  <= 3'd0;
            count <= 4'd0;
            dout  <= 8'd0;
        end else begin
            if (wr_en && !full) begin
                mem[wptr] <= din;
                wptr      <= wptr + 3'd1;
            end
            if (rd_en && !empty) begin
                dout <= mem[rptr];
                rptr <= rptr + 3'd1;
            end
            case ({wr_en && !full, rd_en && !empty})
                2'b10:   count <= count + 4'd1;
                2'b01:   count <= count - 4'd1;
                default: count <= count;
            endcase
        end
    end
endmodule
